PCtrl.Script:
$snapshot = $PowerControl.UI.PendingSnapshot
if ($null -eq $snapshot) {
  $Script:PowerControlItem_Output += [PSCustomObject]@{ Note = 'Pick an earlier output first: right click a repeating job (Repeat...) and choose Previous runs...' }
  return
}
$PowerControl.UI.PendingSnapshot = $null
Add-PowerControlNotification -Source 'Previous run' -Message "$($snapshot.Name) as of $(([datetime]$snapshot.Time).ToString('HH:mm:ss')), $(@($snapshot.Rows).Count) row(s)" -Severity Info
foreach ($row in @($snapshot.Rows)) { if ($null -ne $row) { $Script:PowerControlItem_Output += $row } }

# Two entry points: the View menu (dialog with two job lists) and "Compare with..." in the job menu, which
# hands its choice over in $PowerControl.UI.PendingCompare (AKey/BKey "id|timestamp", or RerunId to run the
# menu again right now, e.g. a fresh clipboard import against the old one).
[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try { $jobs = @($PowerControl.History | Where-Object { $_.NodeType -notin $PowerControl.General.TransientNodeTypes -and $null -ne $_.Output -and @($_.Output).Count -gt 0 }) }
finally { [System.Threading.Monitor]::Exit($PowerControl.HistoryLock) }
$toLine = { param($row) (@($row.PSObject.Properties | ForEach-Object { "$($_.Name)=$($_.Value)" }) -join ' | ') }
# $filters: Summary / Equal / Added / Removed (which statuses to list) and Context (equal rows around a difference even when Equal is off)
$compare = {
  param($nameA, $rowsA, $nameB, $rowsB, [hashtable]$filters)
  $linesA = @($rowsA | ForEach-Object { & $toLine $_ }); $linesB = @($rowsB | ForEach-Object { & $toLine $_ })
  if ($linesA.Count -gt 3000 -or $linesB.Count -gt 3000) { throw "Too many rows for the comparison ($($linesA.Count) / $($linesB.Count), limit 3000)." }
  $diff = @(Get-PowerControlLineDiff -Old $linesA -New $linesB)
  $changed = @($diff | Where-Object { $_.Status -ne 'equal' }).Count
  if ($filters.Summary) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Status = 'summary'; A = $linesA.Count; B = $linesB.Count; Row = "$changed differing rows  (A: $nameA, B: $nameB)" } }
  $keep = [System.Collections.Generic.HashSet[int]]::new()
  for ($k = 0; $k -lt $diff.Count; $k++) {
    $status = $diff[$k].Status
    if (($status -eq 'equal' -and $filters.Equal) -or ($status -eq 'added' -and $filters.Added) -or ($status -eq 'removed' -and $filters.Removed)) { [void]$keep.Add($k) }
    if ($status -ne 'equal' -and $filters.Context -and -not $filters.Equal) { foreach ($c in ($k - 2)..($k + 2)) { if ($c -ge 0 -and $c -lt $diff.Count -and $diff[$c].Status -eq 'equal') { [void]$keep.Add($c) } } }
  }
  for ($k = 0; $k -lt $diff.Count; $k++) {
    if (-not $keep.Contains($k)) { continue }
    $Script:PowerControlItem_Output += [PSCustomObject]@{ Status = $diff[$k].Status; A = $diff[$k].Old; B = $diff[$k].New; Row = $diff[$k].Text }
  }
  if (@($Script:PowerControlItem_Output).Count -eq 0) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Status = 'note'; A = $linesA.Count; B = $linesB.Count; Row = "no rows match the selected statuses ($changed differing rows in total)" } }
}
$filtersFrom = { param($results) @{ Summary = [bool]$results.ShowSummary; Equal = [bool]$results.ShowEqual; Added = [bool]$results.ShowAdded; Removed = [bool]$results.ShowRemoved; Context = [bool]$results.ShowContext } }
# Table layout: both tables side by side in the original columns. Rows are paired by the key column (or by
# position); a changed cell shows "old → new", the Status column says equal / changed / added / removed.
$compareTable = {
  param($nameA, $rowsA, $nameB, $rowsB, [hashtable]$filters, [string]$keyColumn)
  $rowsA = @($rowsA); $rowsB = @($rowsB)
  $columns = [System.Collections.Generic.List[string]]::new()
  foreach ($row in ($rowsA + $rowsB)) { foreach ($name in $row.PSObject.Properties.Name) { if (-not $columns.Contains($name)) { $columns.Add($name) } } }
  $pairs = [System.Collections.Generic.List[object]]::new()
  if ($keyColumn -and $columns.Contains($keyColumn)) {
    $queues = @{}
    foreach ($row in $rowsB) { $k = [string]$row.$keyColumn; if (-not $queues.ContainsKey($k)) { $queues[$k] = [System.Collections.Generic.Queue[object]]::new() }; $queues[$k].Enqueue($row) }
    $matched = [System.Collections.Generic.HashSet[object]]::new([System.Collections.Generic.ReferenceEqualityComparer]::Instance)
    foreach ($row in $rowsA) {
      $k = [string]$row.$keyColumn
      if ($queues.ContainsKey($k) -and $queues[$k].Count -gt 0) { $partner = $queues[$k].Dequeue(); [void]$matched.Add($partner); $pairs.Add(@{ A = $row; B = $partner }) }
      else { $pairs.Add(@{ A = $row; B = $null }) }
    }
    foreach ($row in $rowsB) { if (-not $matched.Contains($row)) { $pairs.Add(@{ A = $null; B = $row }) } }
  }
  else {
    for ($i = 0; $i -lt [Math]::Max($rowsA.Count, $rowsB.Count); $i++) { $pairs.Add(@{ A = $(if ($i -lt $rowsA.Count) { $rowsA[$i] } else { $null }); B = $(if ($i -lt $rowsB.Count) { $rowsB[$i] } else { $null }) }) }
  }
  $counts = @{ equal = 0; changed = 0; added = 0; removed = 0 }
  $result = [System.Collections.Generic.List[object]]::new()
  foreach ($pair in $pairs) {
    $out = [ordered]@{ Status = '' }
    if ($null -ne $pair.A -and $null -ne $pair.B) {
      $status = 'equal'
      foreach ($column in $columns) {
        $valueA = [string]$pair.A.$column; $valueB = [string]$pair.B.$column
        if ($valueA -ceq $valueB) { $out[$column] = $pair.A.$column } else { $out[$column] = "$valueA → $valueB"; $status = 'changed' }
      }
    }
    elseif ($null -ne $pair.A) { $status = 'removed'; foreach ($column in $columns) { $out[$column] = $pair.A.$column } }
    else { $status = 'added'; foreach ($column in $columns) { $out[$column] = $pair.B.$column } }
    $out['Status'] = $status
    $counts[$status]++
    $show = switch ($status) { 'equal' { $filters.Equal } 'changed' { $filters.Added -or $filters.Removed } 'added' { $filters.Added } 'removed' { $filters.Removed } }
    if ($show) { $result.Add([PSCustomObject]$out) }
  }
  if ($filters.Summary) {
    $summary = [ordered]@{ Status = 'summary' }
    foreach ($column in $columns) { $summary[$column] = '' }
    if ($columns.Count -gt 0) { $summary[$columns[0]] = "$($counts.changed) changed, $($counts.added) added, $($counts.removed) removed, $($counts.equal) equal  (A: $nameA $($rowsA.Count) rows, B: $nameB $($rowsB.Count) rows)" }
    $Script:PowerControlItem_Output += [PSCustomObject]$summary
  }
  foreach ($row in $result) { $Script:PowerControlItem_Output += $row }
  if (@($Script:PowerControlItem_Output).Count -eq 0) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Status = 'note'; Row = "no rows match the selected statuses ($($counts.changed) changed, $($counts.added) added, $($counts.removed) removed)" } }
}
$runCompare = {
  param($nameA, $rowsA, $nameB, $rowsB, [hashtable]$filters, [string]$layout, [string]$keyColumn)
  if ($layout -like 'Lines*') { & $compare $nameA $rowsA $nameB $rowsB $filters } else { & $compareTable $nameA $rowsA $nameB $rowsB $filters $keyColumn }
}
$keyFrom = { param($value) $k = [string]$value; if ($k -like '(row position)*') { '' } else { $k } }

$pending = $PowerControl.UI.PendingCompare
if ($null -ne $pending) {
  $PowerControl.UI.PendingCompare = $null
  $filters = if ($pending.Filters) { $pending.Filters } else { @{ Summary = $true; Equal = $false; Added = $true; Removed = $true; Context = $true } }
  $layout = [string]$pending.Layout; $keyColumn = [string]$pending.KeyColumn
  $jobA = $jobs | Where-Object { "$($_.ID)|$($_.Timestamp)" -eq $pending.AKey } | Select-Object -First 1
  if ($null -eq $jobA) { throw 'The job to compare is gone or has no output.' }
  if ($pending.RerunId) {
    # run the menu again in this runspace and compare its fresh rows against the stored job
    $saved = $Script:PowerControlItem_Output
    $Script:PowerControlItem_Output = @()
    $null = Get-ActionSequence -ID $pending.RerunId | Invoke-ActionScript 6>&1
    $fresh = @($Script:PowerControlItem_Output | Where-Object { $null -ne $_ })
    $Script:PowerControlItem_Output = $saved
    & $runCompare "$($jobA.Name) (stored)" @($jobA.Output) "$($jobA.Name) (new run)" $fresh $filters $layout $keyColumn
  }
  elseif ($null -ne $pending.BRows) {
    # a previous run kept by "Repeat..." (OutputHistory): old = the previous run, new = the stored job
    & $runCompare "$($jobA.Name) ($($pending.BName))" @($pending.BRows) "$($jobA.Name) (current)" @($jobA.Output) $filters $layout $keyColumn
  }
  else {
    $jobB = $jobs | Where-Object { "$($_.ID)|$($_.Timestamp)" -eq $pending.BKey } | Select-Object -First 1
    if ($null -eq $jobB) { throw 'The second job is gone or has no output.' }
    & $runCompare $jobA.Name @($jobA.Output) $jobB.Name @($jobB.Output) $filters $layout $keyColumn
  }
  return
}

if ($jobs.Count -lt 2) { throw 'At least two jobs with output are needed (pin a job to keep an older run).' }
$labels = @(); $byLabel = @{}
foreach ($job in $jobs) {
  $stamp = try { [DateTimeOffset]::FromUnixTimeSeconds([long][double]$job.Timestamp).ToLocalTime().ToString('HH:mm:ss') } catch { "$($job.Timestamp)" }
  # single spaces only: XAML collapses whitespace runs in the ComboBoxItem text, the lookup below normalises anyway
  $label = (("$($job.Name) ($stamp, $(@($job.Output).Count) rows)") -replace '\s+', ' ').Trim()
  if ($byLabel.ContainsKey($label)) { continue }
  $labels += $label; $byLabel[$label] = $job
}
$asText = { param($value) $text = if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value }; ($text -replace '\s+', ' ').Trim() }
$keyChoices = @('(row position)') + @(($byLabel[$labels[-1]]).Output[0].PSObject.Properties.Name)
$GUItable = @{
  'window' = @{ 'title' = 'Compare job outputs'; 'description' = 'Table: rows paired by the key column, changed cells as "old → new". Lines: rows as text (column=value | ...), removed = only in A, added = only in B.' }
  'dialog' = @{
    0 = @{ 'Label' = 'Job A (old)'; 'ComboBox' = @{ 'Name' = 'JobA'; 'IsEditable' = $false; 'Text' = $labels[-2]; 'Elements' = $labels } }
    1 = @{ 'Label' = 'Job B (new)'; 'ComboBox' = @{ 'Name' = 'JobB'; 'IsEditable' = $false; 'Text' = $labels[-1]; 'Elements' = $labels } }
    2 = @{ 'Label' = 'Layout'; 'ComboBox' = @{ 'Name' = 'Layout'; 'IsEditable' = $false; 'Text' = 'Table (changed cells as old → new)'; 'Elements' = @('Table (changed cells as old → new)', 'Lines (text diff)') } }
    3 = @{ 'Label' = 'Key column (table layout)'; 'ComboBox' = @{ 'Name' = 'KeyColumn'; 'IsEditable' = $true; 'Text' = $(if ($keyChoices.Count -gt 1) { $keyChoices[1] } else { $keyChoices[0] }); 'Elements' = $keyChoices } }
    4 = @{ 'CheckBox' = @{ 'Name' = 'ShowSummary'; 'Text' = 'Summary row'; 'IsChecked' = $true } }
    5 = @{ 'CheckBox' = @{ 'Name' = 'ShowAdded'; 'Text' = 'added (only in B) and changed'; 'IsChecked' = $true } }
    6 = @{ 'CheckBox' = @{ 'Name' = 'ShowRemoved'; 'Text' = 'removed (only in A) and changed'; 'IsChecked' = $true } }
    7 = @{ 'CheckBox' = @{ 'Name' = 'ShowEqual'; 'Text' = 'equal (in both)'; 'IsChecked' = $false } }
    8 = @{ 'CheckBox' = @{ 'Name' = 'ShowContext'; 'Text' = 'lines layout: two equal rows of context around each difference'; 'IsChecked' = $true } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Compare'; 'Name' = 'Compare'; 'isDefault' = $true } }
  'OnResult' = {
    $jobA = $byLabel[(& $asText $GUIResults.JobA)]; $jobB = $byLabel[(& $asText $GUIResults.JobB)]
    if ($null -eq $jobA -or $null -eq $jobB) { throw 'Select two jobs.' }
    & $runCompare $jobA.Name @($jobA.Output) $jobB.Name @($jobB.Output) (& $filtersFrom $GUIResults) (& $asText $GUIResults.Layout) (& $keyFrom (& $asText $GUIResults.KeyColumn))
  }
}
Show-PCtrlGUI -GUItable $GUItable

$settings = $PowerControl.Settings
$GUItable = @{
  'window' = @{
    'title' = 'Settings'
    'description' = 'Theme and global hotkey apply at once. DebugLevel, interpreters and start states apply from the next start. Bundle sources: folder, .xml URL or GitHub repository/folder.'
  }
  'dialog' = @{
    0 = @{ 'Label' = 'Theme'; 'ComboBox' = @{ 'Name' = 'Theme'; 'IsEditable' = $false; 'Text' = [string]$settings.Theme; 'Elements' = @('System', 'Light', 'Dark') } }
    1 = @{ 'Label' = 'DebugLevel (0-6)'; 'TextBox' = @{ 'Name' = 'DebugLevel'; 'Text' = "$(if ($null -ne $settings.DebugLevel) { $settings.DebugLevel } else { 2 })"; 'check' = { $sender.Text -match '^[0-6]$' } } }
    # prefilled with the interpreter found in PATH or the standard folders, so usually nothing has to be typed
    2 = @{ 'Label' = 'Python'; 'OpenFile' = @{ 'Name' = 'Python'; 'Text' = [string](Find-PowerControlInterpreter -Language Python); 'Filter' = 'Python (python.exe;py.exe)|python.exe;py.exe|All files (*.*)|*.*' } }
    3 = @{ 'Label' = 'Node.js'; 'OpenFile' = @{ 'Name' = 'Node'; 'Text' = [string](Find-PowerControlInterpreter -Language Node); 'Filter' = 'Node (node.exe)|node.exe|All files (*.*)|*.*' } }
    4 = @{ 'CheckBox' = @{ 'Name' = 'NavigationPinned'; 'Text' = 'Navigation pinned at start'; 'IsChecked' = [bool]$settings.NavigationPinned } }
    5 = @{ 'CheckBox' = @{ 'Name' = 'JobsPinned'; 'Text' = 'Job list open at start'; 'IsChecked' = [bool]$settings.JobsPinned } }
    6 = @{ 'CheckBox' = @{ 'Name' = 'ActionsPinned'; 'Text' = 'Actions panel pinned at start (otherwise icon rail)'; 'IsChecked' = -not [bool]$settings.ActionsCollapsed } }
    7 = @{ 'CheckBox' = @{ 'Name' = 'RestorePinnedTabs'; 'Text' = 'Run pinned menus again at the next start'; 'IsChecked' = ($settings.RestorePinnedTabs -ne $false) } }
    8 = @{ 'CheckBox' = @{ 'Name' = 'NotifyOnFinish'; 'Text' = 'Notify when a longer job finishes in the background'; 'IsChecked' = ($settings.NotifyOnFinish -ne $false) } }
    9 = @{ 'Label' = 'Bundle sources (; separated)'; 'TextBox' = @{ 'Name' = 'BundleSources'; 'Text' = (@($settings.BundleSources) -join '; ') } }
    10 = @{ 'Label' = 'Global hotkey (e.g. Ctrl+Alt+P, empty = off)'; 'TextBox' = @{ 'Name' = 'GlobalHotkey'; 'Text' = [string]$settings.GlobalHotkey; 'ToolTip' = 'System wide shortcut that brings PowerControl to the front from any program. Modifiers: Ctrl, Alt, Shift, Win.' } }
    11 = @{ 'Label' = 'Script editor colors'; 'ComboBox' = @{ 'Name' = 'CodeEditorColors'; 'IsEditable' = $false; 'Text' = $(if ($settings.CodeEditorColors -eq 'Light') { 'Light' } else { 'Auto' }); 'Elements' = @('Auto', 'Light'); 'ToolTip' = 'Auto: the script editor in dialogs follows the theme (dark background, brightened syntax colors). Light: white editor with the standard colors even in the dark theme. Applies to the next dialog.' } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Save'; 'Name' = 'Save'; 'isDefault' = $true } }
  'OnResult' = {
    $theme = if ($GUIResults.Theme -is [string]) { $GUIResults.Theme } else { [string]$GUIResults.Theme.Content }
    if ($theme -in 'System', 'Light', 'Dark') { $settings.Theme = $theme }
    if ("$($GUIResults.DebugLevel)" -match '^[0-6]$') { $settings.DebugLevel = [int]$GUIResults.DebugLevel }
    $settings.Interpreters = @{ Python = [string]$GUIResults.Python; Node = [string]$GUIResults.Node }
    $settings.NavigationPinned = [bool]$GUIResults.NavigationPinned
    $settings.JobsPinned = [bool]$GUIResults.JobsPinned
    $settings.ActionsCollapsed = -not [bool]$GUIResults.ActionsPinned
    $settings.RestorePinnedTabs = [bool]$GUIResults.RestorePinnedTabs
    $settings.NotifyOnFinish = [bool]$GUIResults.NotifyOnFinish
    # folders, .xml URLs or GitHub repository/folder URLs; fetched at start and via Customization > Bundles abrufen
    $settings.BundleSources = @(([string]$GUIResults.BundleSources) -split ';' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
    $settings.GlobalHotkey = ([string]$GUIResults.GlobalHotkey).Trim()
    $settings.CodeEditorColors = $(if ("$($GUIResults.CodeEditorColors.Content)" -eq 'Light') { 'Light' } else { 'Auto' })
    Save-PowerControlSettings
    Set-PowerControlTheme -Theme $settings.Theme -NoSave
    Invoke-PowerControlUICommand -Name RegisterHotkey
  }
}
Show-PCtrlGUI -GUItable $GUItable

$settings = $PowerControl.Settings
$defaultPath = Join-Path $PowerControl.General.ExportPath ("PowerControl-Settings-{0:yyyyMMdd-HHmm}.json" -f (Get-Date))
$GUItable = @{
  'window' = @{ 'title' = 'Export settings'; 'description' = 'Everything except RecentMenus, PinnedMenus and the bundle hashes. Import it on the other side with Customization > Import settings...' }
  'dialog' = @{
    0 = @{ 'Label' = 'File'; 'TextBox' = @{ 'Name' = 'Path'; 'Text' = $defaultPath; 'Focus' = $true } }
    1 = @{ 'CheckBox' = @{ 'Name' = 'WithInterpreters'; 'Text' = 'Include interpreter paths (machine specific)'; 'IsChecked' = $false } }
    2 = @{ 'CheckBox' = @{ 'Name' = 'WithProfiles'; 'Text' = 'Include column profiles'; 'IsChecked' = $true } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Export'; 'Name' = 'Export'; 'isDefault' = $true } }
  'OnResult' = {
    $path = ([string]$GUIResults.Path).Trim('"', ' ')
    if (-not $path) { throw 'No file name given.' }
    $skip = @('RecentMenus', 'PinnedMenus', 'BundleState', 'ImportPaths', 'ElementBundles')
    if (-not [bool]$GUIResults.WithInterpreters) { $skip += 'Interpreters' }
    if (-not [bool]$GUIResults.WithProfiles) { $skip += 'ColumnProfiles' }
    $export = [ordered]@{ PowerControlSettings = $PowerControl.General.Version; ExportedFrom = $env:COMPUTERNAME; Exported = (Get-Date).ToString('s') }
    foreach ($key in @($settings.Keys | Sort-Object)) { if ($skip -notcontains $key) { $export[$key] = $settings[$key] } }
    $directory = [System.IO.Path]::GetDirectoryName($path)
    if ($directory -and -not (Test-Path -LiteralPath $directory)) { New-Item -ItemType Directory -Path $directory -Force | Out-Null }
    [System.IO.File]::WriteAllText($path, (ConvertTo-Json -InputObject $export -Depth 8), [System.Text.UTF8Encoding]::new($false))
    foreach ($key in @($export.Keys)) { if ($key -notin 'PowerControlSettings', 'ExportedFrom', 'Exported') { $Script:PowerControlItem_Output += [PSCustomObject]@{ Setting = $key; Result = 'exported'; File = $path } } }
  }
}
Show-PCtrlGUI -GUItable $GUItable

$settings = $PowerControl.Settings
$GUItable = @{
  'window' = @{ 'title' = 'Import settings'; 'description' = 'Lists (favorites, bundle sources) are merged, everything else in the file replaces the current value. Theme and hotkey apply at once, start options from the next start.' }
  'dialog' = @{
    0 = @{ 'Label' = 'File'; 'OpenFile' = @{ 'Name' = 'Path'; 'Text' = ''; 'Filter' = 'PowerControl settings (*.json)|*.json|All files (*.*)|*.*' } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Import'; 'Name' = 'Import'; 'isDefault' = $true } }
  'OnResult' = {
    $path = ([string]$GUIResults.Path).Trim('"', ' ')
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { throw "File not found: $path" }
    $data = Get-Content -LiteralPath $path -Raw | ConvertFrom-Json -AsHashtable
    if ($null -eq $data -or -not $data.ContainsKey('PowerControlSettings')) { throw 'Not a PowerControl settings export (missing PowerControlSettings marker).' }
    $merge = @('FavoriteActions', 'FavoriteMenus', 'BundleSources')
    foreach ($key in @($data.Keys | Sort-Object)) {
      if ($key -in 'PowerControlSettings', 'ExportedFrom', 'Exported', 'RecentMenus', 'PinnedMenus', 'BundleState') { continue }
      if ($merge -contains $key) {
        $before = @($settings[$key] | Where-Object { $_ })
        $settings[$key] = @($before + @($data[$key] | Where-Object { $_ }) | Select-Object -Unique)
        $Script:PowerControlItem_Output += [PSCustomObject]@{ Setting = $key; Result = "merged ($(@($settings[$key]).Count - $before.Count) new)"; File = $path }
      }
      else {
        $settings[$key] = $data[$key]
        $Script:PowerControlItem_Output += [PSCustomObject]@{ Setting = $key; Result = 'replaced'; File = $path }
      }
    }
    Save-PowerControlSettings
    if ($data.ContainsKey('Theme')) { Set-PowerControlTheme -Theme ([string]$settings.Theme) -NoSave }
    Invoke-PowerControlUICommand -Name RegisterHotkey
    Invoke-PowerControlUICommand -Name RefreshFavorites
  }
}
Show-PCtrlGUI -GUItable $GUItable

$tool = Join-Path $PowerControl.General.CurrentPath 'tools\Test-EngineXml.ps1'
if (-not (Test-Path -LiteralPath $tool)) { throw "Validator not found: $tool" }
$findings = @(& $tool -EngineFolder $PowerControl.General.enginePath -PassThru)
if ($findings.Count -eq 0) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Severity = 'OK'; File = ''; Element = ''; Message = 'no findings: every engine file parses, every reference resolves, every icon exists' } }
else { $Script:PowerControlItem_Output += $findings }

$logPath = [System.IO.Path]::Combine($PowerControl.General.CurrentPath, 'ini', 'changes.json')
if (-not (Test-Path -LiteralPath $logPath)) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Time = ''; User = ''; Machine = ''; File = ''; Element = 'no changes logged yet'; Change = ''; ID = '' }; return }
$entries = @(Get-Content -LiteralPath $logPath -Raw | ConvertFrom-Json)
foreach ($entry in ($entries | Sort-Object Time -Descending | Select-Object -First 500)) {
  $Script:PowerControlItem_Output += [PSCustomObject]@{ Time = ([datetime]$entry.Time).ToString('yyyy-MM-dd HH:mm:ss'); User = $entry.User; Machine = $entry.Machine; File = $entry.File; Element = $entry.Label; Change = $entry.Change; ID = $entry.ID }
}

# helper functions for "Show diff", "Restore version" and "Compare job outputs" (PrevAction, never shown itself)
function script:Get-PowerControlLineDiff {
    <# LCS based line diff: rows with Status equal|removed|added, Old/New line numbers and the text #>
    param ([string[]]$Old, [string[]]$New)
    $n = $Old.Count; $m = $New.Count
    $table = New-Object 'int[,]' ($n + 1), ($m + 1)
    for ($i = $n - 1; $i -ge 0; $i--) {
        for ($j = $m - 1; $j -ge 0; $j--) {
            $table[$i, $j] = if ($Old[$i] -ceq $New[$j]) { $table[($i + 1), ($j + 1)] + 1 } else { [Math]::Max($table[($i + 1), $j], $table[$i, ($j + 1)]) }
        }
    }
    $i = 0; $j = 0
    while ($i -lt $n -or $j -lt $m) {
        if ($i -lt $n -and $j -lt $m -and $Old[$i] -ceq $New[$j]) { [PSCustomObject]@{ Status = 'equal'; Old = $i + 1; New = $j + 1; Text = $Old[$i] }; $i++; $j++ }
        elseif ($j -lt $m -and ($i -ge $n -or $table[$i, ($j + 1)] -ge $table[($i + 1), $j])) { [PSCustomObject]@{ Status = 'added'; Old = ''; New = $j + 1; Text = $New[$j] }; $j++ }
        else { [PSCustomObject]@{ Status = 'removed'; Old = $i + 1; New = ''; Text = $Old[$i] }; $i++ }
    }
}
function script:Get-PowerControlHistorySnapshot {
    <#
      ini\history\<ID>\<stamp>.xml holds the version of an element BEFORE each change (Write-PowerControlChangeLog).
      Returns @{ Old = <file of the version replaced by the change at $Time>; Next = <following snapshot or $null> }
    #>
    param ([string]$Id, [datetime]$Time)
    $folder = [System.IO.Path]::Combine($PowerControl.General.CurrentPath, 'ini', 'history', ($Id -replace '[^A-Za-z0-9_.-]', '_'))
    $snapshots = @(if (Test-Path -LiteralPath $folder) { Get-ChildItem -LiteralPath $folder -Filter '*.xml' -File | Sort-Object Name })
    $old = $null; $next = $null
    foreach ($snapshot in $snapshots) {
        $stamp = [datetime]::ParseExact($snapshot.BaseName.Substring(0, 15), 'yyyyMMdd-HHmmss', $null)
        if ($stamp -le $Time.AddSeconds(2)) { $old = $snapshot } elseif ($null -eq $next) { $next = $snapshot }
    }
    @{ Old = $old; Next = $next }
}

if (-not (Test-Path $PowerControl.General.ExportPath)) { New-Item -Path $PowerControl.General.ExportPath -ItemType Directory | Out-Null }
$data = Get-PowerControlGridData
$rows = @($data.Rows)
if ($rows.Count -eq 0) { throw 'No rows available.' }
$columns = if ($data.Columns.Count -gt 0) { @($data.Columns) } else { @($rows[0].PSObject.Properties.Name) }
$encode = { param($value) [System.Net.WebUtility]::HtmlEncode([string]$value) }
$title = "PowerControl diff $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
$style = '<style>body{font-family:Segoe UI,Arial,sans-serif;font-size:12px;margin:16px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:3px 8px;text-align:left;vertical-align:top;font-family:Consolas,monospace;white-space:pre-wrap}th{background:#eee;font-family:Segoe UI,Arial,sans-serif}tr.added td{background:#e6ffed;color:#22863a}tr.removed td{background:#ffeef0;color:#b31d28}tr.changed td{background:#fff8c5}tr.summary td,tr.note td{background:#f1f8ff;font-weight:600;font-family:Segoe UI,Arial,sans-serif}tr.equal td{color:#555}.legend span{display:inline-block;padding:2px 8px;margin-right:8px;border:1px solid #ccc}</style>'
$html = [System.Text.StringBuilder]::new()
[void]$html.Append("<!DOCTYPE html><html><head><meta charset=`"utf-8`"><title>$(& $encode $title)</title>$style</head><body><h2>$(& $encode $title)</h2>")
[void]$html.Append('<p class="legend"><span style="background:#e6ffed">added</span><span style="background:#ffeef0">removed</span><span style="background:#fff8c5">changed (old → new)</span><span>equal</span></p><table><tr>')
foreach ($column in $columns) { [void]$html.Append("<th>$(& $encode $column)</th>") }
[void]$html.Append('</tr>')
foreach ($row in $rows) {
    $status = ([string]$row.Status).ToLowerInvariant() -replace '[^a-z]', ''
    [void]$html.Append("<tr class=`"$status`">")
    foreach ($column in $columns) { [void]$html.Append("<td>$(& $encode $row.$column)</td>") }
    [void]$html.Append('</tr>')
}
[void]$html.Append('</table></body></html>')
$reportPath = Join-Path $PowerControl.General.ExportPath 'Diff.html'
[System.IO.File]::WriteAllText($reportPath, $html.ToString(), [System.Text.UTF8Encoding]::new($true))
Invoke-Item -Path $reportPath
$Script:PowerControlItem_Output += [PSCustomObject]@{ Exported = $rows.Count; File = $reportPath }

foreach ($row in @($script:SelectedEntries | Where-Object { $_.ID })) {
    $entryTime = try { [datetime]::ParseExact([string]$row.Time, 'yyyy-MM-dd HH:mm:ss', $null) } catch { Get-Date }
    $snapshot = Get-PowerControlHistorySnapshot -Id ([string]$row.ID) -Time $entryTime
    if ($null -eq $snapshot.Old) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Result = 'no previous version stored (entry older than the history or newly created element)'; File = [string]$row.File }; continue }
    $fragment = [System.Xml.XmlDocument]::new(); $fragment.PreserveWhitespace = $true; $fragment.Load($snapshot.Old.FullName)
    $fileName = [string]$row.File
    if (-not $fileName) { throw "No file recorded for $($row.Element)" }
    $path = Join-Path $PowerControl.General.enginePath $fileName
    $doc = [System.Xml.XmlDocument]::new(); $doc.PreserveWhitespace = $true
    if (Test-Path -LiteralPath $path) { $doc.Load($path) } else { [void]$doc.AppendChild($doc.CreateXmlDeclaration('1.0', 'utf-8', $null)); [void]$doc.AppendChild($doc.CreateElement('Engine')) }
    $imported = $doc.ImportNode($fragment.DocumentElement, $true)
    $current = $doc.SelectSingleNode("//PCtrl[@ID='$(([string]$row.ID).Replace("'", '&apos;'))']")
    if ($null -ne $current) { [void]$current.ParentNode.ReplaceChild($imported, $current); $what = 'replaced the current version' }
    else { [void]$doc.DocumentElement.AppendChild($doc.CreateWhitespace("`n  ")); [void]$doc.DocumentElement.AppendChild($imported); [void]$doc.DocumentElement.AppendChild($doc.CreateWhitespace("`n")); $what = 're-added (element was removed)' }
    Save-PowerControlXml -XmlDocument $doc -Path $path -RefreshIndex
    $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Result = "restored version $($snapshot.Old.BaseName.Substring(0, 15)), $what"; File = $fileName }
}

# Old = the snapshot taken at this change (the version before it), new = the following snapshot or the element as it is now
foreach ($row in @($script:SelectedEntries | Where-Object { $_.ID })) {
    $entryTime = try { [datetime]::ParseExact([string]$row.Time, 'yyyy-MM-dd HH:mm:ss', $null) } catch { Get-Date }
    $snapshot = Get-PowerControlHistorySnapshot -Id ([string]$row.ID) -Time $entryTime
    if ($null -eq $snapshot.Old) {
        $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Status = 'no previous version stored (entry older than the history or newly created element)'; Old = ''; New = ''; Text = '' }
        continue
    }
    $oldText = Get-Content -LiteralPath $snapshot.Old.FullName -Raw
    $newText = if ($null -ne $snapshot.Next) { Get-Content -LiteralPath $snapshot.Next.FullName -Raw } else { $current = Get-ElementByIdFromIndex -id ([string]$row.ID); if ($null -ne $current) { $current.PCtrl.OuterXml } else { '' } }
    $source = if ($null -ne $snapshot.Next) { "version $($snapshot.Next.BaseName.Substring(0, 15))" } elseif ($newText) { 'current file' } else { 'element removed' }
    $oldLines = @($oldText -split '\r?\n'); $newLines = @($newText -split '\r?\n')
    if ($oldLines.Count -gt 3000 -or $newLines.Count -gt 3000) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Status = 'too large for the line comparison'; Old = $oldLines.Count; New = $newLines.Count; Text = $snapshot.Old.FullName }; continue }
    $diff = @(Get-PowerControlLineDiff -Old $oldLines -New $newLines)
    # changed lines with two lines of context
    $keep = [System.Collections.Generic.HashSet[int]]::new()
    for ($k = 0; $k -lt $diff.Count; $k++) { if ($diff[$k].Status -ne 'equal') { foreach ($c in ($k - 2)..($k + 2)) { if ($c -ge 0 -and $c -lt $diff.Count) { [void]$keep.Add($c) } } } }
    $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Status = "old: $($snapshot.Old.BaseName.Substring(0, 15))  new: $source"; Old = $oldLines.Count; New = $newLines.Count; Text = "$(@($diff | Where-Object { $_.Status -ne 'equal' }).Count) changed lines" }
    for ($k = 0; $k -lt $diff.Count; $k++) {
        if (-not $keep.Contains($k)) { continue }
        $Script:PowerControlItem_Output += [PSCustomObject]@{ Element = [string]$row.Element; Status = $diff[$k].Status; Old = $diff[$k].Old; New = $diff[$k].New; Text = $diff[$k].Text }
    }
}

$settings = $PowerControl.Settings
if ($null -eq $settings['ElementBundles']) { $settings['ElementBundles'] = @{} }
$engineFiles = @(Get-ChildItem -Path (Join-Path $PowerControl.General.enginePath '*.xml') | ForEach-Object { $_.Name })
$asText = { param($value) if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value } }

$GUItable = @{
  'window' = @{
    'title' = 'Import elements'
    'description' = 'Takes a bundle file written by "Export elements..." into an engine file. Existing IDs are skipped or replaced.'
  }
  'dialog' = @{
    0 = @{ 'Label' = 'Bundle'; 'OpenFile' = @{ 'Name' = 'Bundle'; 'Text' = [string]$settings['ElementBundles']['LastExport']; 'Filter' = 'PowerControl bundle (*.xml)|*.xml|All files (*.*)|*.*' } }
    1 = @{ 'Label' = 'Target file'; 'ComboBox' = @{ 'Name' = 'Target'; 'IsEditable' = $true; 'Text' = 'Imported.xml'; 'Elements' = @(@('Imported.xml') + $engineFiles | Select-Object -Unique) } }
    2 = @{ 'Label' = 'If the ID exists'; 'ComboBox' = @{ 'Name' = 'Conflict'; 'IsEditable' = $false; 'Text' = 'Skip'; 'Elements' = @('Skip', 'Replace') } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Import'; 'Name' = 'Import'; 'isDefault' = $true } }
  'OnResult' = {
    $bundlePath = ([string]$GUIResults.Bundle).Trim('"', ' ')
    $targetName = (& $asText $GUIResults.Target).Trim()
    $replace = (& $asText $GUIResults.Conflict) -eq 'Replace'
    # the merge itself lives in the core (Import-PowerControlBundle), shared with the bundle subscriptions
    $Script:PowerControlItem_Output += Import-PowerControlBundle -Path $bundlePath -TargetName $targetName -Replace:$replace
    $settings['ElementBundles']['LastImport'] = $bundlePath
    Save-PowerControlSettings
  }
}
Show-PCtrlGUI -GUItable $GUItable

$settings = $PowerControl.Settings
if ($null -eq $settings['ElementBundles']) { $settings['ElementBundles'] = @{} }
$selected = @($script:SelectedEntries | Where-Object { $_.id })
if ($selected.Count -eq 0) { throw 'No elements selected.' }
$defaultPath = Join-Path $PowerControl.General.ExportPath ("PowerControl-Elements-{0:yyyyMMdd-HHmm}.xml" -f (Get-Date))

$GUItable = @{
  'window' = @{
    'title' = 'Export elements'
    'description' = "Writes $($selected.Count) selected element(s) as a bundle. The bundle is a normal engine file and can also be copied straight into engine\."
  }
  'dialog' = @{
    0 = @{ 'Label' = 'File'; 'TextBox' = @{ 'Name' = 'Path'; 'Text' = $defaultPath; 'Focus' = $true } }
    1 = @{ 'CheckBox' = @{ 'Name' = 'WithDependencies'; 'Text' = 'Include dependencies (PrevAction, NextAction, Children)'; 'IsChecked' = $true } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Export'; 'Name' = 'Export'; 'isDefault' = $true } }
  'OnResult' = {
    $path = ([string]$GUIResults.Path).Trim('"', ' ')
    if (-not $path) { throw 'No file name given.' }
    $withDependencies = [bool]$GUIResults.WithDependencies

    $bundle = [System.Xml.XmlDocument]::new(); $bundle.PreserveWhitespace = $true
    [void]$bundle.AppendChild($bundle.CreateXmlDeclaration('1.0', 'utf-8', $null))
    $root = $bundle.AppendChild($bundle.CreateElement('Engine'))
    [void]$root.AppendChild($bundle.CreateWhitespace("`n  "))
    [void]$root.AppendChild($bundle.CreateComment(" PowerControl element bundle, exported $(Get-Date -Format 'yyyy-MM-dd HH:mm') from $env:COMPUTERNAME. Import: Customization > Import elements... "))

    $queue = [System.Collections.Generic.Queue[string]]::new()
    foreach ($row in $selected) { $queue.Enqueue([string]$row.id) }
    $done = [System.Collections.Generic.HashSet[string]]::new()
    while ($queue.Count -gt 0) {
      $id = $queue.Dequeue()
      if (-not $done.Add($id)) { continue }
      $element = Get-ElementByIdFromIndex -id $id
      if ($null -eq $element) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = ''; ID = $id; Result = 'not found'; File = '' }; continue }
      $node = $element.DocumentElement
      [void]$root.AppendChild($bundle.CreateWhitespace("`n  "))
      [void]$root.AppendChild($bundle.ImportNode($node, $true))
      $source = ($PowerControl.JsonCache.PCtrlItems | Where-Object { $_.id -eq $id } | Select-Object -First 1).file
      $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = $node.GetAttribute('Label'); ID = $id; Result = $(if ($selected.id -contains $id) { 'exported' } else { 'exported (dependency)' }); File = $source }
      if ($withDependencies) {
        foreach ($ref in @($node.SelectNodes('PrevAction/@ID | NextAction/@ID'))) { $queue.Enqueue($ref.Value) }
        foreach ($child in ([string]$node.GetAttribute('Children')).Split(',')) { if ($child.Trim()) { $queue.Enqueue($child.Trim()) } }
      }
    }
    [void]$root.AppendChild($bundle.CreateWhitespace("`n"))
    Save-PowerControlXml -XmlDocument $bundle -Path $path
    $settings['ElementBundles']['LastExport'] = $path
    Save-PowerControlSettings
    $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = '(bundle)'; ID = ''; Result = "$($done.Count) element(s) written"; File = $path }
  }
}
Show-PCtrlGUI -GUItable $GUItable

function New-XMLElement {
  param (
      [Parameter(Mandatory=$true)]
      [string]$Name,
      [hashtable]$Attributes = @{},
      [string]$InnerText = "",
      [scriptblock]$ChildElements = {}
  )

  $element = $xml.CreateElement($Name)

  foreach ($key in $Attributes.Keys) {
      $element.SetAttribute($key, $Attributes[$key])
  }

  if ($InnerText -ne "") {
      $element.InnerText = $InnerText
  }

  $childNodes = & $ChildElements
  if ($childNodes -is [array]) {
      foreach ($node in $childNodes) {
          [void]$element.AppendChild($node)
      }
  } elseif ($childNodes -is [System.Xml.XmlNode]) {
      [void]$element.AppendChild($childNodes)
  }

  return $element
}

function script:Convert-XAMLtoWindow {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory = $true, ValueFromPipeline = $true)]
        [ValidateNotNullOrEmpty()]
        [string] $XAML
    )

    process {
        try {
            Add-Type -AssemblyName PresentationFramework
            $reader = [XML.XMLReader]::Create([IO.StringReader]$XAML)
            $result = [Windows.Markup.XAMLReader]::Load($reader)
        }
        catch {
            Write-Error "Failed to parse XAML: $_"
            return
        }
        finally {
            $reader.Close()
        }

        $reader = [XML.XMLReader]::Create([IO.StringReader]$XAML)
        try {
            while ($reader.Read()) {
                $name = $reader.GetAttribute('Name') ?? $reader.GetAttribute('x:Name')
                if ($name) {
                    $element = $result.FindName($name)
                    if ($element) {
                        $result.PSObject.Properties.Add([PSNoteProperty]::new($name, $element))
                    }
                }
            }
        }
        catch {
            Write-Error "Error processing XAML elements: $_"
        }
        finally {
            $reader.Close()
        }

        $result
    }
}

function script:Show-WPFWindow {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory = $true)]
        [ValidateNotNull()]
        [Windows.Window]$Window
    )

    # registered dialogs are closed by the main window on shutdown, otherwise this runspace could never end
    # direct assignment on purpose: inside an if-expression an (empty) list would be enumerated and become $null
    $openDialogs = $null
    if ($null -ne $PowerControl -and $null -ne $PowerControl.UI) { $openDialogs = $PowerControl.UI.OpenDialogs }
    try {
        if ($null -ne $openDialogs) { [void]$openDialogs.Add($Window) }
        if (Get-Command Write-DebugLog -ErrorAction SilentlyContinue) { Write-DebugLog -Message "Show-WPFWindow: '$($Window.Title)' registered: $($null -ne $openDialogs) (open dialogs: $(if ($null -ne $openDialogs) { $openDialogs.Count } else { 'n/a' }))" -Level 2 -LogFileName 'UI.log' }
        $dispatcher = [System.Windows.Threading.Dispatcher]::CurrentDispatcher
        $dispatcherFrame = [System.Windows.Threading.DispatcherFrame]::new()
        $dispatcher.BeginInvoke([Windows.Threading.DispatcherPriority]::Normal, [Action]{
            $Window.ShowDialog()
            $dispatcherFrame.Continue = $false
        })
        [System.Windows.Threading.Dispatcher]::PushFrame($dispatcherFrame)
    }
    catch {
        Write-Error "Error showing WPF window: $_"
    }
    finally {
        if ($null -ne $openDialogs) { $openDialogs.Remove($Window) }
    }
}



    $script:DrawGUIID = $script:PowerControlID

function script:Add-WPFElement {
    param (
        [System.Text.StringBuilder]$xamlBuilder,
        [hashtable]$element,
        [int]$depth = 0,
        [int]$row = 0,
        [int]$column = 1
    )

    $indent = "    " * $depth

    $controlName = ''

    Write-DebugLog -Message "Processing element: $($element.Keys | Where-Object { $_ -ne 'Label' } | Select-Object -First 1)" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    switch ($element.Keys | Where-Object { $_ -ne 'Label' } | Select-Object -First 1) {
        'GroupBox' {
            Write-DebugLog -Message "Adding GroupBox: $($element.GroupBox.Header)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

            $xamlBuilder.Append("`n$indent<GroupBox Header=`"$($element.GroupBox.Header)`" Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            $xamlBuilder.Append("`n$indent    <StackPanel>") | Out-Null

            foreach ($nestedElement in $element.GroupBox.Elements) {
                if ($nestedElement.Label) {
                    $xamlBuilder.Append("`n$indent        <TextBlock Text=`"$($nestedElement.Label)`" Margin=`"5,5,5,0`"/>") | Out-Null
                }
                Add-WPFElement -xamlBuilder $xamlBuilder -element $nestedElement -depth ($depth + 2)
            }

            $xamlBuilder.Append("`n$indent    </StackPanel>") | Out-Null
            $xamlBuilder.Append("`n$indent</GroupBox>") | Out-Null
        }

        'TextBox' {
            $controlName = "$($element.TextBox.Name)_$script:controlCounter"
            $script:controlCounter++

            # Multi-line boxes used to sit inside a ScrollViewer that carried no Grid.Row/Grid.Column, so the
            # wrapper landed in row 0 / column 0 and covered the first label. The TextBox scrolls on its own now.
            $xamlBuilder.Append("`n$indent<TextBox Name=`"$controlName`" ") | Out-Null
            if ($element.TextBox.IsEnabled -eq $false) {
                $xamlBuilder.Append('IsEnabled="false" ') | Out-Null
            }
            # read-only (unlike disabled) keeps the text selectable, e.g. to copy an element ID
            if ($element.TextBox.IsReadOnly -eq $true) {
                $xamlBuilder.Append('IsReadOnly="True" ') | Out-Null
            }
            if ($element.TextBox.Width) {
                $xamlBuilder.Append("Width=`"$($element.TextBox.Width)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Width=`"Auto`" ") | Out-Null
            }

            if ($element.TextBox.Height) {
                $xamlBuilder.Append("Height=`"$($element.TextBox.Height)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Height=`"Auto`" ") | Out-Null
            }
            if ($element.TextBox.MultiLine -eq $true) {
                $xamlBuilder.Append('AcceptsReturn="True" TextWrapping="Wrap" VerticalScrollBarVisibility="Auto" MaxHeight="300" ') | Out-Null
                if (-not $element.TextBox.Height) { $xamlBuilder.Append('MinHeight="90" ') | Out-Null }
                if (-not $element.TextBox.Width) { $xamlBuilder.Append('MinWidth="320" ') | Out-Null }
                $xamlBuilder.Append('FontFamily="Consolas" ') | Out-Null
            }
            if ($element.TextBox.ToolTip) {
                $xamlBuilder.Append("ToolTip=`"$($element.TextBox.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            $xamlBuilder.Append("</TextBox>") | Out-Null

            Write-DebugLog -Message "Adding TextBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'TextBlock' {
            $controlName = "$($element.TextBlock.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<TextBlock Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Text=`"$($element.TextBlock.Text)`" ") | Out-Null
            if ($element.TextBlock.FontSize) {
                $xamlBuilder.Append("FontSize=`"$($element.TextBlock.FontSize)`" ") | Out-Null
            }
            if ($element.TextBlock.FontWeight) {
                $xamlBuilder.Append("FontWeight=`"$($element.TextBlock.FontWeight)`" ") | Out-Null
            }
            if ($element.TextBlock.Foreground) {
                $xamlBuilder.Append("Foreground=`"$($element.TextBlock.Foreground)`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added TextBlock: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'CodeEditor' { 
            if(Test-Path $($Global:PowerControl.General.CurrentPath  + '\dll\ICSharpCode.AvalonEdit.dll')) {
                $controlName = "$($element.CodeEditor.Name)_$script:controlCounter"
                $script:controlCounter++

                # the editor may take about half of the working area, so the fields below it stay on screen
                $editorMaxHeight = if ($script:DrawGuiMaxEditorHeight -gt 0) { $script:DrawGuiMaxEditorHeight } else { 800 }
                $xamlBuilder.Append("`n$indent<ScrollViewer VerticalScrollBarVisibility=`"Auto`" HorizontalScrollBarVisibility=`"Auto`" MaxHeight=`"$editorMaxHeight`" MaxWidth=`"2000`" Grid.Row=`"$row`" Grid.Column=`"$column`">") | Out-Null
                $xamlBuilder.Append("`n$indent<avalon:TextEditor Name=`"$controlName`" ") | Out-Null
                if ($element.CodeEditor.Syntax) {
                    $xamlBuilder.Append("SyntaxHighlighting=`"$($element.CodeEditor.Syntax)`" ") | Out-Null
                }
                else {
                    $xamlBuilder.Append("SyntaxHighlighting=`"PowerShell`" ") | Out-Null
                }

                $xamlBuilder.Append("ShowLineNumbers=`"True`" ") | Out-Null
                if ($element.CodeEditor.ToolTip) {
                    $xamlBuilder.Append("ToolTip=`"$($element.CodeEditor.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" ") | Out-Null
                }

                if ($element.CodeEditor.MinWidth) {
                    $xamlBuilder.Append("MinWidth=`"$($element.CodeEditor.MinWidth)`" ") | Out-Null
                }
                else {
                    $xamlBuilder.Append("MinWidth=`"500`" ") | Out-Null
                }

                if ($element.CodeEditor.MinHeight) {
                    $xamlBuilder.Append("MinHeight=`"$($element.CodeEditor.MinHeight)`" ") | Out-Null
                }
                else {
                    $xamlBuilder.Append("MinHeight=`"250`" ") | Out-Null
                }

                $xamlBuilder.Append("HorizontalScrollBarVisibility=`"Auto`" ") | Out-Null
                $xamlBuilder.Append("VerticalScrollBarVisibility=`"Auto`" ") | Out-Null
                $xamlBuilder.Append("FontFamily=`"Consolas`" ") | Out-Null
                $xamlBuilder.Append("FontSize=`"14`" ") | Out-Null
                # AvalonEdit has no Fluent template: colors come from the dialog resources set in Show-WPFWindow (light / dark)
                $xamlBuilder.Append("Background=`"{DynamicResource PowerControlEditorBackgroundBrush}`" Foreground=`"{DynamicResource PowerControlEditorForegroundBrush}`" LineNumbersForeground=`"{DynamicResource PowerControlEditorForegroundBrush}`" ") | Out-Null
                #$xamlBuilder.Append("PreviewMouseWheel=`"TextEditor_PreviewMouseWheel`" ") | Out-Null
                $xamlBuilder.Append("/>") | Out-Null
                $xamlBuilder.Append("`n$indent</ScrollViewer>") | Out-Null
                Write-DebugLog -Message "Added CodeEditor: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
            }
        }

        'PasswordBox' {
            $controlName = "$($element.PasswordBox.Name)_$script:controlCounter"
            $script:controlCounter++
            $passwordToolTip = if ($element.PasswordBox.ToolTip) { "ToolTip=`"$($element.PasswordBox.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" " } else { '' }
            $xamlBuilder.Append("`n$indent<PasswordBox Name=`"$controlName`" ${passwordToolTip}Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added PasswordBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'CheckBox' {
            $controlName = "$($element.CheckBox.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<CheckBox Name=`"$controlName`" Content=`"$($element.CheckBox.Text)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" ") | Out-Null
            if ($element.CheckBox.IsChecked -eq $true) {
                $xamlBuilder.Append('IsChecked="True" ') | Out-Null
            }
            if ($element.CheckBox.ToolTip) {
                $xamlBuilder.Append("ToolTip=`"$($element.CheckBox.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" ") | Out-Null
            }
            $xamlBuilder.Append('Margin="5"/>') | Out-Null

            Write-DebugLog -Message "Added CheckBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'ComboBox' {
            $controlName = "$($element.ComboBox.Name)_$script:controlCounter"
            $script:controlCounter++
            # IconPreview: every entry is an icon path relative to icons\ and is shown with the rendered icon;
            # the value travels in the item's Tag (Get-ControlValues hands it back as .Content like a plain entry).
            # A preview box right of the ComboBox follows the typed or selected value (Add-ComboBoxIconPreview).
            $iconPreview = $element.ComboBox.IconPreview -eq $true -and (Get-Command New-PowerControlIconXaml -ErrorAction SilentlyContinue)
            if ($iconPreview) {
                $xamlBuilder.Append("`n$indent<DockPanel LastChildFill=`"True`" Grid.Row=`"$row`" Grid.Column=`"$column`"><Border Name=`"${controlName}_Preview`" DockPanel.Dock=`"Left`" Width=`"28`" Height=`"28`" Margin=`"5,0,0,0`" VerticalAlignment=`"Center`" ToolTip=`"Preview of the selected icon`"/>") | Out-Null
            }
            $xamlBuilder.Append("`n$indent<ComboBox Name=`"$controlName`" ") | Out-Null
            if ($element.ComboBox.IsEditable -eq $true) {
                $xamlBuilder.Append('IsEditable="True" ') | Out-Null
            }
            if ($element.ComboBox.Width) {
                $xamlBuilder.Append("Width=`"$($element.ComboBox.Width)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Width=`"Auto`" ") | Out-Null
            }

            if ($element.ComboBox.Height) {
                $xamlBuilder.Append("Height=`"$($element.ComboBox.Height)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Height=`"Auto`" ") | Out-Null
            }
            if ($element.ComboBox.HorizontalAlignment) {
                $xamlBuilder.Append("HorizontalAlignment=`"$($element.ComboBox.HorizontalAlignment)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("HorizontalAlignment=`"Stretch`" ") | Out-Null
            }
            if ($element.ComboBox.ToolTip) {
                $xamlBuilder.Append("ToolTip=`"$($element.ComboBox.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" ") | Out-Null
            }
            if ($iconPreview) { $xamlBuilder.Append("TextSearch.TextPath=`"Tag`" MaxDropDownHeight=`"420`" ") | Out-Null }
            $comboText = $element.ComboBox.Text ? $element.ComboBox.Text.Replace('<', '&lt;').Replace('>', '&gt;') : ($element.ComboBox.Elements | Select-Object -First 1)
            if ($iconPreview) { $xamlBuilder.Append("Text=`"$comboText`" Margin=`"5`">") | Out-Null }
            else { $xamlBuilder.Append("Text=`"$comboText`" Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null }

            foreach ($comboElement in $element.ComboBox.Elements) {
                $selected = if ($element.ComboBox.Text -and $element.ComboBox.Text -eq $comboElement) { ' IsSelected="True"' } else { '' }
                $escaped = $comboElement.Replace('<','&lt;').Replace('>','&gt;')
                if ($iconPreview) {
                    $iconXaml = New-PowerControlIconXaml -Icon $comboElement -Size 16 -Margin '0'
                    $xamlBuilder.Append("`n$indent    <ComboBoxItem Tag=`"$escaped`"$selected><StackPanel Orientation=`"Horizontal`"><Grid Width=`"18`" Height=`"18`" VerticalAlignment=`"Center`">$iconXaml</Grid><TextBlock Text=`"$escaped`" Margin=`"8,0,0,0`" VerticalAlignment=`"Center`"/></StackPanel></ComboBoxItem>") | Out-Null
                }
                else {
                    $xamlBuilder.Append("`n$indent    <ComboBoxItem$selected>$escaped</ComboBoxItem>") | Out-Null
                }
            }

            $xamlBuilder.Append("`n$indent</ComboBox>") | Out-Null
            if ($iconPreview) { $xamlBuilder.Append("`n$indent</DockPanel>") | Out-Null }

            Write-DebugLog -Message "Added ComboBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'RadioButton' {
            $controlName = "$($element.RadioButton.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<RadioButton Name=`"$controlName`" Content=`"$($element.RadioButton.Text)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added RadioButton: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Slider' {
            $controlName = "$($element.Slider.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Slider Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Minimum=`"$($element.Slider.Minimum)`" Maximum=`"$($element.Slider.Maximum)`" ") | Out-Null
            $xamlBuilder.Append("Value=`"$($element.Slider.Value)`" ") | Out-Null
            if ($element.Slider.Width) {
                $xamlBuilder.Append("Width=`"$($element.Slider.Width)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Width=`"Auto`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added Slider: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'DatePicker' {
            $controlName = "$($element.DatePicker.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<DatePicker Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added DatePicker: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'ListBox' {
            $controlName = "$($element.ListBox.Name)_$script:controlCounter"
            $script:controlCounter++

            $selectionMode = if ($element.ListBox.SelectionMode) {
                $element.ListBox.SelectionMode
            } else {
                "Extended"
            }

            $xamlBuilder.Append("`n$indent<ListBox Name=`"$controlName`" ") | Out-Null
            if ($element.ListBox.ToolTip) {
                $xamlBuilder.Append("ToolTip=`"$($element.ListBox.ToolTip.Replace('<','&lt;').Replace('>','&gt;').Replace('"','&quot;'))`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`" SelectionMode=`"$selectionMode`">") | Out-Null
            foreach ($item in $element.ListBox.Items) {
                $xamlBuilder.Append("`n$indent    <ListBoxItem>$item</ListBoxItem>") | Out-Null
            }
            $xamlBuilder.Append("`n$indent</ListBox>") | Out-Null

            Write-DebugLog -Message "Added ListBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'ProgressBar' {
            $controlName = "$($element.ProgressBar.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<ProgressBar Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Minimum=`"$($element.ProgressBar.Minimum)`" Maximum=`"$($element.ProgressBar.Maximum)`" ") | Out-Null
            $xamlBuilder.Append("Value=`"$($element.ProgressBar.Value)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added ProgressBar: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Image' {
            $controlName = "$($element.Image.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Image Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Source=`"$($element.Image.Source)`" ") | Out-Null
            $xamlBuilder.Append("Width=`"$($element.Image.Width)`" Height=`"$($element.Image.Height)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added Image: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Button' {
            $controlName = "$($element.Button.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Button Name=`"$controlName`" Content=`"$($element.Button.Content)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added Button: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'TabControl' {
            $controlName = "$($element.TabControl.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<TabControl Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            foreach ($tab in $element.TabControl.Tabs) {
                $xamlBuilder.Append("`n$indent    <TabItem Header=`"$($tab.Header)`">") | Out-Null
                $xamlBuilder.Append("`n$indent        <StackPanel>") | Out-Null
                foreach ($tabElement in $tab.Elements) {
                    Add-WPFElement -xamlBuilder $xamlBuilder -element $tabElement -depth ($depth + 3)
                }
                $xamlBuilder.Append("`n$indent        </StackPanel>") | Out-Null
                $xamlBuilder.Append("`n$indent    </TabItem>") | Out-Null
            }
            $xamlBuilder.Append("`n$indent</TabControl>") | Out-Null

            Write-DebugLog -Message "Added TabControl: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'StackPanel' {
            $controlName = "$($element.StackPanel.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<StackPanel Name=`"$controlName`" ") | Out-Null

            # Add Orientation if specified
            if ($element.StackPanel.Orientation) {
                $xamlBuilder.Append("Orientation=`"$($element.StackPanel.Orientation)`" ") | Out-Null
            }

            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null

            foreach ($stackPanelElement in $element.StackPanel.Elements) {
                Add-WPFElement -xamlBuilder $xamlBuilder -element $stackPanelElement -depth ($depth + 1)
            }

            $xamlBuilder.Append("`n$indent</StackPanel>") | Out-Null

            Write-DebugLog -Message "Added StackPanel: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Expander' {
            $controlName = "$($element.Expander.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Expander Name=`"$controlName`" Header=`"$($element.Expander.Header)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            $xamlBuilder.Append("`n$indent    <StackPanel>") | Out-Null
            foreach ($expanderElement in $element.Expander.Elements) {
                Add-WPFElement -xamlBuilder $xamlBuilder -element $expanderElement -depth ($depth + 2)
            }
            $xamlBuilder.Append("`n$indent    </StackPanel>") | Out-Null
            $xamlBuilder.Append("`n$indent</Expander>") | Out-Null

            Write-DebugLog -Message "Added Expander: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'TreeView' {
            $controlName = "$($element.TreeView.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<TreeView Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            foreach ($item in $element.TreeView.Items) {
                $xamlBuilder.Append("`n$indent    <TreeViewItem Header=`"$($item.Header)`">") | Out-Null
                if ($item.Items) {
                    foreach ($subItem in $item.Items) {
                        $xamlBuilder.Append("`n$indent        <TreeViewItem Header=`"$subItem`"/>") | Out-Null
                    }
                }
                $xamlBuilder.Append("`n$indent    </TreeViewItem>") | Out-Null
            }
            $xamlBuilder.Append("`n$indent</TreeView>") | Out-Null

            Write-DebugLog -Message "Added TreeView: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'DataGrid' {
            $controlName = "$($element.DataGrid.Name)_$script:controlCounter"
            $script:controlCounter++
            # Filter: a text box above the grid narrows the entries of every ComboBoxColumn (Add-DataGridColumnsAndRows)
            if ($element.DataGrid.Filter -eq $true) {
                $xamlBuilder.Append("`n$indent<StackPanel Grid.Row=`"$row`" Grid.Column=`"$column`"><TextBlock Text=`"Filter the choice lists (part of the name, applies when a cell is opened next)`" Opacity=`"0.7`" FontSize=`"11`" Margin=`"5,2,5,0`"/><TextBox Name=`"${controlName}_Filter`" Margin=`"5,2,5,0`" ToolTip=`"Narrows the entries of the choice columns of this table`"/>") | Out-Null
            }
            $xamlBuilder.Append("`n$indent<DataGrid Name=`"$controlName`" AutoGenerateColumns=`"False`" ") | Out-Null

            if ($element.DataGrid.Width) {
                $xamlBuilder.Append("Width=`"$($element.DataGrid.Width)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Width=`"Auto`" ") | Out-Null
            }

            if ($element.DataGrid.Height) {
                $xamlBuilder.Append("Height=`"$($element.DataGrid.Height)`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Height=`"Auto`" ") | Out-Null
            }

            if ($element.DataGrid.CanUserSortColumns -eq $false) {
                $xamlBuilder.Append("CanUserSortColumns=`"False`" ") | Out-Null
            }
            if ($element.DataGrid.CanUserReorderColumns -eq $false) {
                $xamlBuilder.Append("CanUserReorderColumns=`"False`" ") | Out-Null
            }
            if ($element.DataGrid.CanUserResizeColumns -eq $false) {
                $xamlBuilder.Append("CanUserResizeColumns=`"False`" ") | Out-Null
            }
            if ($element.DataGrid.IsReadOnly -eq $true) {
                $xamlBuilder.Append("IsReadOnly=`"True`" ") | Out-Null
            }
            if ($element.DataGrid.SelectionMode) {
                $xamlBuilder.Append("SelectionMode=`"$($element.DataGrid.SelectionMode)`" ") | Out-Null
            }
            if ($element.DataGrid.SelectionUnit) {
                $xamlBuilder.Append("SelectionUnit=`"$($element.DataGrid.SelectionUnit)`" ") | Out-Null
            }
            if ($element.DataGrid.AlternatingRowBackground) {
                $xamlBuilder.Append("AlternatingRowBackground=`"$($element.DataGrid.AlternatingRowBackground)`" ") | Out-Null
            }

            if ($element.DataGrid.AddRows) {
                $xamlBuilder.Append("CanUserAddRows=`"False`" ") | Out-Null
            }

            $xamlBuilder.Append("HorizontalAlignment=`"Stretch`" VerticalAlignment=`"Stretch`" ") | Out-Null
            if ($element.DataGrid.Filter -eq $true) { $xamlBuilder.Append("Margin=`"5`"/>`n$indent</StackPanel>") | Out-Null }
            else { $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null }

            Write-DebugLog -Message "Added DataGrid: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'RichTextBox' {
            $controlName = "$($element.RichTextBox.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<RichTextBox Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            $xamlBuilder.Append("`n$indent    <FlowDocument>") | Out-Null
            $xamlBuilder.Append("`n$indent        <Paragraph>") | Out-Null
            $xamlBuilder.Append("`n$indent            <Run>$($element.RichTextBox.Text)</Run>") | Out-Null
            $xamlBuilder.Append("`n$indent        </Paragraph>") | Out-Null
            $xamlBuilder.Append("`n$indent    </FlowDocument>") | Out-Null
            $xamlBuilder.Append("`n$indent</RichTextBox>") | Out-Null

            Write-DebugLog -Message "Added RichTextBox: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'ToggleButton' {
            $controlName = "$($element.ToggleButton.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<ToggleButton Name=`"$controlName`" Content=`"$($element.ToggleButton.Content)`" ") | Out-Null
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added ToggleButton: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'ScrollViewer' {
            $controlName = "$($element.ScrollViewer.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<ScrollViewer Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("VerticalScrollBarVisibility=`"Auto`" HorizontalScrollBarVisibility=`"Auto`" ") | Out-Null
            if ($element.ScrollViewer.Width) {
                $xamlBuilder.Append("Width=`"$($element.ScrollViewer.Width)`" ") | Out-Null
            }
            if ($element.ScrollViewer.Height) {
                $xamlBuilder.Append("Height=`"$($element.ScrollViewer.Height)`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null
            $xamlBuilder.Append("`n$indent    <StackPanel>") | Out-Null
            foreach ($scrollElement in $element.ScrollViewer.Elements) {
                Add-WPFElement -xamlBuilder $xamlBuilder -element $scrollElement -depth ($depth + 2)
            }
            $xamlBuilder.Append("`n$indent    </StackPanel>") | Out-Null
            $xamlBuilder.Append("`n$indent</ScrollViewer>") | Out-Null

            Write-DebugLog -Message "Added ScrollViewer: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Border' {
            $controlName = "$($element.Border.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Border Name=`"$controlName`" ") | Out-Null
            $xamlBuilder.Append("BorderBrush=`"$($element.Border.BorderBrush)`" BorderThickness=`"$($element.Border.BorderThickness)`" ") | Out-Null
            if ($element.Border.Background) {
                $xamlBuilder.Append("Background=`"$($element.Border.Background)`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`">") | Out-Null

            # Check if there's only one element and it's a TextBlock
            if ($element.Border.Elements.Count -eq 1 -and $element.Border.Elements[0].ContainsKey('TextBlock')) {
                $textBlock = $element.Border.Elements[0].TextBlock
                $xamlBuilder.Append("`n$indent    <TextBlock Name=`"$($textBlock.Name)`" Text=`"$($textBlock.Text)`"/>") | Out-Null
            } else {
                $xamlBuilder.Append("`n$indent    <StackPanel>") | Out-Null
                foreach ($borderElement in $element.Border.Elements) {
                    Add-WPFElement -xamlBuilder $xamlBuilder -element $borderElement -depth ($depth + 2)
                }
                $xamlBuilder.Append("`n$indent    </StackPanel>") | Out-Null
            }

            $xamlBuilder.Append("`n$indent</Border>") | Out-Null

            Write-DebugLog -Message "Added Border: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'Separator' {
            $controlName = "$($element.Separator.Name)_$script:controlCounter"
            $script:controlCounter++
            $xamlBuilder.Append("`n$indent<Separator Name=`"$controlName`" ") | Out-Null
            if ($element.Separator.Orientation -eq 'Vertical') {
                $xamlBuilder.Append("Width=`"1`" ") | Out-Null
            } else {
                $xamlBuilder.Append("Height=`"1`" ") | Out-Null
            }
            $xamlBuilder.Append("Grid.Row=`"$row`" Grid.Column=`"$column`" Margin=`"5`"/>") | Out-Null

            Write-DebugLog -Message "Added Separator: $controlName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }

        'OpenFile' {
              $controlName = "$($element.OpenFile.Name)_$script:controlCounter"
              $buttonName = "OpenFile_$($element.OpenFile.Name)_$script:controlCounter"
              $script:controlCounter++

              $xamlBuilder.Append("`n$indent<Grid Grid.Row=`"$row`" Grid.Column=`"$column`">") | Out-Null
              $xamlBuilder.Append("`n$indent    <Grid.ColumnDefinitions>") | Out-Null
              $xamlBuilder.Append("`n$indent        <ColumnDefinition Width=`"*`"/>") | Out-Null
              $xamlBuilder.Append("`n$indent        <ColumnDefinition Width=`"Auto`"/>") | Out-Null
              $xamlBuilder.Append("`n$indent    </Grid.ColumnDefinitions>") | Out-Null
              $xamlBuilder.Append("`n$indent    <TextBox x:Name=`"$controlName`" Grid.Column=`"0`" Margin=`"5,5,0,5`"/>") | Out-Null
              $browseSize = if ((-not $PowerControl.General.Theme) -or ($PowerControl.General.Theme -eq 'Classic')) { 'Width="25"' } else { 'MinWidth="40" Padding="8,0"' }
              $xamlBuilder.Append("`n$indent    <Button x:Name=`"$buttonName`" Content=`"...`" Grid.Column=`"1`" $browseSize Margin=`"0,5,5,5`"/>") | Out-Null
              $xamlBuilder.Append("`n$indent</Grid>") | Out-Null

              Write-DebugLog -Message "Added OpenFile: TextBox = $controlName, Button = $buttonName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
          }
    }
    if ($controlName.Length -gt 0) {
        $script:WPFCollector += [PSCustomObject]@{
            'Label' = $element.Label
            'WPFElement' = $element.Keys | Where-Object { $_ -ne 'Label' } | Select-Object -First 1
            'WPFName' = $controlName
            'Properties' = $($element.GetEnumerator() | Where-Object { $_.Key -notin @('Label') }).value.GetEnumerator() | Where-Object { $_.Key -notin @('Name') }
        }
    }
    Write-DebugLog -Message "Finished processing element" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
}

function script:Get-ControlValues {
    param ([System.Windows.DependencyObject]$Container)

    Write-DebugLog -Message "Starting Get-ControlValues function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    $results = @{}

    foreach($element in $script:WPFCollector){
        switch ($element.WPFElement) {
            "TextBox" { $results[$element.WPFName] = $container.$($element.WPFName).Text }
            "CodeEditor" { $results[$element.WPFName] = $container.$($element.WPFName).Text }
            "OpenFile" { $results[$element.WPFName] = $container.$($element.WPFName).Text }
            "PasswordBox" { $results[$element.WPFName] = $container.$($element.WPFName).SecurePassword }
            "CheckBox" { $results[$element.WPFName] = $container.$($element.WPFName).IsChecked }
            "ComboBox" {
                # an editable ComboBox with free text has no SelectedItem; hand the text back in the
                # same shape (.Content) so consumers like "New element" keep working
                $combo = $container.$($element.WPFName)
                $results[$element.WPFName] = if ($null -ne $combo.SelectedItem -and $combo.SelectedItem -is [System.Windows.Controls.ComboBoxItem] -and $null -ne $combo.SelectedItem.Tag) {
                    # IconPreview entries: the value is the Tag, the Content is the icon + text panel
                    [PSCustomObject]@{ Content = [string]$combo.SelectedItem.Tag }
                } elseif ($null -ne $combo.SelectedItem) {
                    $combo.SelectedItem
                } elseif ($combo.IsEditable -and -not [string]::IsNullOrEmpty($combo.Text)) {
                    [PSCustomObject]@{ Content = $combo.Text }
                } else {
                    $null
                }
            }
            "DatePicker" { $results[$element.WPFName] = $container.$($element.WPFName).SelectedDate }
            "Slider" { $results[$element.WPFName] = $container.$($element.WPFName).Value }
            "ListBox" { $results[$element.WPFName] = $container.$($element.WPFName).SelectedItems }
            "RadioButton" { if ($container.$($element.WPFName).IsChecked) { $results[$element.WPFName] = $container.$($element.WPFName).Content } }
            "DataGrid" { $results[$element.WPFName] = $container.$($element.WPFName).ItemsSource }
            "RichTextBox" { 
                $textRange = New-Object System.Windows.Documents.TextRange(
                    $container.$($element.WPFName).Document.ContentStart, 
                    $container.$($element.WPFName).Document.ContentEnd
                )
                $results[$element.WPFName] = $textRange.Text 
            }
            "ToggleButton" { $results[$element.WPFName] = $container.$($element.WPFName).IsChecked }
            "ItemsListBox" { 
                $results[$element.WPFName] = @{
                    AllItems = $container.$($element.WPFName).ItemsSource
                    SelectedItems = $container.$($element.WPFName).SelectedItems
                }
            }
        }
    }

    Write-DebugLog -Message "Finished Get-ControlValues function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
    return $results
}

function script:Add-DataGridColumnsAndRows {
    param ($DataGrid, $Element)

    Write-DebugLog -Message "Starting Add-DataGridColumnsAndRows function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    $script:dataCollection = New-Object System.Collections.ObjectModel.ObservableCollection[object]
    $control = $DataGrid.FindName($Element.WPFName)

    $Columns = $($Element.Properties | Where-Object { $_.Key -eq 'columns' }).Value
    $Rows = $($Element.Properties | Where-Object { $_.Key -eq 'Rows' }).Value
    $comboSources = @{}   # resource key -> full entry list of a ComboBoxColumn (for the Filter box)

    if ($Columns.count -gt  0) {
        $Columns.foreach{
            $items = $_
            $column = switch ($items.Type) {
                'TextColumn' { 
                    $col = New-Object System.Windows.Controls.DataGridTextColumn
                    $col.Binding = New-Object System.Windows.Data.Binding($items.Binding)
                    $col
                }
                'CheckBoxColumn' { 
                    $col = New-Object System.Windows.Controls.DataGridCheckBoxColumn
                    $col.Binding = New-Object System.Windows.Data.Binding($items.Binding)
                    $col
                }
                'ComboBoxColumn' {
                    # The Fluent theme (.NET 10) has no usable template for DataGridComboBoxColumn: its dropdown opened
                    # as an empty white box (Workflow tab of the element editor). A template column with an ordinary
                    # ComboBox renders in both themes; the entries live in a DataGrid resource (DynamicResource).
                    $resourceKey = "ComboItems_$($items.Binding -replace '[^A-Za-z0-9_]', '')_$([guid]::NewGuid().ToString('N').Substring(0, 6))"
                    $control.Resources[$resourceKey] = [string[]]@($items.Items | ForEach-Object { [string]$_ })
                    $comboSources[$resourceKey] = [string[]]@($items.Items | ForEach-Object { [string]$_ })
                    $templateXaml = @"
<DataGridTemplateColumn xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <DataGridTemplateColumn.CellTemplate><DataTemplate><TextBlock Text="{Binding $($items.Binding)}" Margin="4,2" VerticalAlignment="Center"/></DataTemplate></DataGridTemplateColumn.CellTemplate>
  <DataGridTemplateColumn.CellEditingTemplate><DataTemplate><ComboBox ItemsSource="{DynamicResource $resourceKey}" IsEditable="True" Text="{Binding $($items.Binding), UpdateSourceTrigger=PropertyChanged}" IsTextSearchEnabled="True" MaxDropDownHeight="360"/></DataTemplate></DataGridTemplateColumn.CellEditingTemplate>
</DataGridTemplateColumn>
"@
                    [Windows.Markup.XamlReader]::Parse($templateXaml)
                 }
                default { 
                    $col = New-Object System.Windows.Controls.DataGridTextColumn
                    $col.Binding = New-Object System.Windows.Data.Binding($items.Binding)
                    $col
                 }
            }

            $column.Header = $items.Header

            if ($items.Width) {
                $column.Width = if ($items.Width -eq 'Auto') { [System.Windows.Controls.DataGridLength]::Auto } else { New-Object System.Windows.Controls.DataGridLength($items.Width) }
            }
            if ($items.IsReadOnly -eq $true) { $column.IsReadOnly = $true }
            if ($items.CanUserSort -eq $false) { $column.CanUserSort = $false }

            $control.Columns.Add($column)
            Write-DebugLog -Message "Added column: $($items.Header)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }
    }

    # DataGrid option Filter: the text box above the grid narrows every ComboBoxColumn list (DynamicResource swap)
    $filterBox = $DataGrid.FindName("$($Element.WPFName)_Filter")
    if ($null -ne $filterBox -and $comboSources.Count -gt 0) {
        $filterBox.Tag = @{ Grid = $control; Sources = $comboSources }
        $filterBox.Add_TextChanged({
            param($sender, $e)
            $state = $sender.Tag
            $needle = ([string]$sender.Text).Trim()
            foreach ($key in @($state.Sources.Keys)) {
                $all = $state.Sources[$key]
                $state.Grid.Resources[$key] = [string[]]@($(if ($needle) { $all | Where-Object { $_ -like "*$needle*" } } else { $all }))
            }
        })
    }

    if ($Rows.count -gt  0) {

        if($rows[0].GetType().FullName -ne 'System.Management.Automation.PSCustomObject') {
            $Rows.foreach{
                $Row = $_
                $customObject = [PSCustomObject]@{}

                $properties = @{}
                foreach ($key in $Row.Keys) {
                    $properties[$key] = $Row[$key]
                }

                $customObject = [PSCustomObject]$properties
                $script:dataCollection.Add($customObject)
            }
        }
        else {
            $script:dataCollection += $Rows
        }

        $control.ItemsSource = $script:dataCollection
        Write-DebugLog -Message "Added $($Rows.Count) rows to DataGrid" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    }

    if ($($Element.Properties | Where-Object { $_.Key -eq 'AddRows' }).Value) {
        Write-DebugLog -Message "Adding AddRows event to Button" -Level 3 -LogFileName $($script:DrawGUIID + '.log')

        $newRow = @{}
        foreach ($property in $columns.Binding) {
            $newRow[$property] = ""
        }
        <#foreach ($property in $script:dataCollection[0].PSObject.Properties.Name) {
            $newRow[$property] = ""
        }
        #>
        if($script:dataCollection.count -gt 0) {
            $script:dataCollection += $([PSCustomObject]$newRow)
        }
        else {
            $script:dataCollection.Add($([PSCustomObject]$newRow))
        }

        $control.ItemsSource = $script:dataCollection
        $control.Items.Refresh()

        $control.add_PreviewKeyUp([System.Management.Automation.ScriptBlock]::Create('
            param($sender, $e)

            if ($e.Key -eq "Delete") {
                $currentRow = $sender.SelectedItem
                if ($currentRow -ne $null -and $script:dataCollection.Count -gt 1) {
                    if ($script:dataCollection -isnot [System.Collections.ArrayList]) {
                        $script:dataCollection = [System.Collections.ArrayList]::new($script:dataCollection)
                    }

                    $currentIndex = $script:dataCollection.IndexOf($currentRow)
                    if ($currentIndex -ge 0) {
                        [void]$script:dataCollection.RemoveAt($currentIndex)
                        $sender.ItemsSource = $null
                        $sender.ItemsSource = $script:dataCollection
                        $sender.Items.Refresh()
                        $e.Handled = $true
                    }
                }
            }
            elseif ($e.Key -eq "Tab" -or $e.Key -eq "Return") {
                $lastRowIndex = $script:dataCollection.Count - 1
                $currentRow = $sender.CurrentItem
                $currentIndex = $sender.Items.IndexOf($currentRow)

                if ($currentIndex -eq $lastRowIndex) {
                    $hasContent = $false
                    foreach ($property in $currentRow.PSObject.Properties) {
                        if (![string]::IsNullOrWhiteSpace($property.Value)) {
                            $hasContent = $true
                            break
                        }
                    }

                    if ($hasContent) {
                        $newRow = [PSCustomObject]@{}
                        foreach ($property in $script:dataCollection[0].PSObject.Properties.Name) {
                            $newRow | Add-Member -MemberType NoteProperty -Name $property -Value ""
                        }                
                        $script:dataCollection += $newRow
                        $sender.ItemsSource = $script:dataCollection
                        $sender.Items.Refresh()
                    }
                }
            }
'))

        $control.add_SelectionChanged([System.Management.Automation.ScriptBlock]::Create('
            param($sender, $e)

                $lastRowIndex = $script:dataCollection.Count - 1
                $currentRow = $sender.CurrentItem
                $currentIndex = $sender.Items.IndexOf($currentRow)

                if ($currentIndex -eq $lastRowIndex) {
                    $hasContent = $false
                    foreach ($property in $currentRow.PSObject.Properties) {
                        if (![string]::IsNullOrWhiteSpace($property.Value)) {
                            $hasContent = $true
                            break
                        }
                    }

                    if ($hasContent) {
                        $newRow = [PSCustomObject]@{}
                        foreach ($property in $script:dataCollection[0].PSObject.Properties.Name) {
                            $newRow | Add-Member -MemberType NoteProperty -Name $property -Value ""
                        }                
                        $script:dataCollection += $newRow
                        $sender.ItemsSource = $script:dataCollection
                        $sender.Items.Refresh()
                    }
                }

'))

    }


    Write-DebugLog -Message "Finished Add-DataGridColumnsAndRows function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
}

function script:ConvertTo-NormalizedGuiResults {
    param ([Parameter(Mandatory=$true)][hashtable]$GuiResults)

    Write-DebugLog -Message "Starting ConvertTo-NormalizedGuiResults function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    $normalizedResults = @{}

    foreach ($key in $GuiResults.Keys) {
        $baseName = $key -replace '_\d+$', ''

        if ($normalizedResults.ContainsKey($baseName)) {
            if ($normalizedResults[$baseName] -isnot [System.Collections.ArrayList]) {
                $normalizedResults[$baseName] = [System.Collections.ArrayList]@($normalizedResults[$baseName])
            }
            $null = $normalizedResults[$baseName].Add($GuiResults[$key])
            Write-DebugLog -Message "Added value to existing key: $baseName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        } else {
            $normalizedResults[$baseName] = $GuiResults[$key]
            Write-DebugLog -Message "Added new key-value pair: $baseName" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        }
    }

    Write-DebugLog -Message "Finished ConvertTo-NormalizedGuiResults function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
    return $normalizedResults
}

function script:Invoke-GUIElementProcessing {
    param (
        [Parameter(Mandatory=$true)]$Elements,
        [System.Windows.Controls.ContentControl]$ParentControl
    )

    Write-DebugLog -Message "Starting GUI Element Processing" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    foreach($element in $script:WPFCollector){
        Write-DebugLog -Message "Processing Name: $($element.WPFName) element: $($element.WPFElement)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

        switch ($element.WPFElement) {
            'OpenFile' { 
                Write-DebugLog -Message "Invoking OpenFile Processing" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
                Invoke-OpenFileProcessing $element $ParentControl
            }
            {'TextBox','CheckBox','ComboBox','CodeEditor' -contains $_} {
                Write-DebugLog -Message "Invoking Common Control Processing for $($element.WPFElement)" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
                Invoke-CommonControlProcessing $element $ParentControl
                if ($element.WPFElement -eq 'ComboBox') { Add-ComboBoxIconPreview -Element $element -Window $ParentControl }
            }

            'ListBox' {
                Write-DebugLog -Message "Invoking Common Control Processing for $($element.WPFElement)" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
                Invoke-ListBoxProcessing $element $ParentControl
            }

            'DataGrid' {
                Write-DebugLog -Message "Invoking Common Control Processing for $($element.WPFElement)" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
                Add-DataGridColumnsAndRows -DataGrid $ParentControl -Element $element
            }
        }
    }
    #
    Write-DebugLog -Message "Finished GUI Element Processing" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
}


function script:Test-DrawGuiEditorDark {
    <# $true when the script editor should use the dark palette: dark theme and setting CodeEditorColors not 'Light' #>
    param([string]$EffectiveTheme)
    if ($EffectiveTheme -ne 'Dark') { return $false }
    $colors = ''
    try { if ($null -ne $PowerControl.Settings) { $colors = [string]$PowerControl.Settings['CodeEditorColors'] } } catch { }
    return ($colors -ne 'Light')
}

function script:Set-DrawGuiDarkHighlighting {
    <#
      AvalonEdit's built-in PowerShell colors (dark blue, dark red, ...) are unreadable on a dark background.
      A private copy of the highlighting definition is loaded from the AvalonEdit resources and every color is
      lifted to a lightness of about 70 %; the shared definition (used by light dialogs) stays untouched.
    #>
    param($Editor)
    try {
        $name = if ($Editor.SyntaxHighlighting) { $Editor.SyntaxHighlighting.Name } else { 'PowerShell' }
        $assembly = [ICSharpCode.AvalonEdit.TextEditor].Assembly
        $resource = @($assembly.GetManifestResourceNames() | Where-Object { $_ -eq "ICSharpCode.AvalonEdit.Highlighting.Resources.$name.xshd" })
        if ($resource.Count -eq 0) { return }
        $stream = $assembly.GetManifestResourceStream([string]$resource[0])
        $reader = [System.Xml.XmlReader]::Create([System.IO.Stream]$stream)
        $definition = [ICSharpCode.AvalonEdit.Highlighting.Xshd.HighlightingLoader]::Load([System.Xml.XmlReader]$reader, [ICSharpCode.AvalonEdit.Highlighting.IHighlightingDefinitionReferenceResolver][ICSharpCode.AvalonEdit.Highlighting.HighlightingManager]::Instance)
        $reader.Dispose(); $stream.Dispose()
        foreach ($color in $definition.NamedHighlightingColors) {
            if ($null -eq $color.Foreground) { continue }
            $c = $color.Foreground.GetBrush($null).Color
            $r = $c.R / 255.0; $g = $c.G / 255.0; $b = $c.B / 255.0
            $max = [Math]::Max($r, [Math]::Max($g, $b)); $min = [Math]::Min($r, [Math]::Min($g, $b)); $l = ($max + $min) / 2
            if ($l -ge 0.62) { continue }
            $d = $max - $min
            $s = if ($d -eq 0) { 0 } else { $d / (1 - [Math]::Abs(2 * $l - 1)) }
            $h = if ($d -eq 0) { 0 } elseif ($max -eq $r) { 60 * ((($g - $b) / $d) % 6) } elseif ($max -eq $g) { 60 * ((($b - $r) / $d) + 2) } else { 60 * ((($r - $g) / $d) + 4) }
            if ($h -lt 0) { $h += 360 }
            $l = 0.72
            $chroma = (1 - [Math]::Abs(2 * $l - 1)) * $s; $x = $chroma * (1 - [Math]::Abs(($h / 60) % 2 - 1)); $m = $l - $chroma / 2
            $rgb = switch ([int][Math]::Floor($h / 60)) { 0 { @($chroma, $x, 0) } 1 { @($x, $chroma, 0) } 2 { @(0, $chroma, $x) } 3 { @(0, $x, $chroma) } 4 { @($x, 0, $chroma) } default { @($chroma, 0, $x) } }
            $color.Foreground = [ICSharpCode.AvalonEdit.Highlighting.SimpleHighlightingBrush]::new([System.Windows.Media.Color]::FromRgb([byte](($rgb[0] + $m) * 255), [byte](($rgb[1] + $m) * 255), [byte](($rgb[2] + $m) * 255)))
        }
        $Editor.SyntaxHighlighting = $definition
    }
    catch { Write-DebugLog -Message "Dark highlighting not applied: $_" -Level 2 -LogFileName $($script:DrawGUIID + '.log') }
}

function script:Invoke-CommonControlProcessing {
    param($element, $Window)

    Write-DebugLog -Message "Invoke-CommonControlProcessing" -Level 3 -LogFileName $($script:DrawGUIID + '.log')

    $control = $Window.FindName($element.WPFName)

    if ($control) {
        switch -Wildcard ($element.Properties.key) {
            'Text' {
                # a CheckBox carries its 'Text' as Content (set in the XAML); assigning .Text there threw
                # "property 'Text' cannot be found" and closed the whole dialog from the Loaded handler
                if ($null -ne $control.PSObject.Properties['Text']) {
                    $control.Text = $($element.Properties | Where-Object { $_.Key -eq 'Text' }).Value
                }
            }
            'IsChecked' {
                if ($null -ne $control.PSObject.Properties['IsChecked']) {
                    $control.IsChecked = $($element.Properties | Where-Object { $_.Key -eq 'IsChecked' }).Value
                }
            }
            'Events' {
                # $element is the WPFCollector entry (PSCustomObject), the dialog definition lives in .Properties
                $events = $($element.Properties | Where-Object { $_.Key -eq 'Events' }).Value
                foreach ($eventName in $events.Keys) {
                    $eventScript = [System.Management.Automation.ScriptBlock]::Create($events[$eventName])
                    $control."add_$eventName"($eventScript)
                }
            }
            'Check' {
                Add-CheckHandler $control $($element.Properties | Where-Object { $_.Key -eq 'check' }).Value
            }
        }

        if($element.WPFElement -eq 'CodeEditor') {
            if ($script:DrawGuiEditorDark) { Set-DrawGuiDarkHighlighting -Editor $control }
            $control.add_PreviewMouseWheel({
                param($sender, $e)

                # Find the parent ScrollViewer
                $scrollViewer = $sender.Parent
                while ($scrollViewer -and -not ($scrollViewer -is [System.Windows.Controls.ScrollViewer])) {
                    $scrollViewer = $scrollViewer.Parent
                }

                # Forward the scroll event to the parent ScrollViewer
                if ($scrollViewer) {
                    $scrollViewer.ScrollToVerticalOffset($scrollViewer.VerticalOffset - $e.Delta)
                    $e.Handled = $true
                }
            })

            $control.add_PreviewKeyDown({
                param($sender, $e)

                # Find the parent ScrollViewer
                $scrollViewer = $sender.Parent
                while ($scrollViewer -and -not ($scrollViewer -is [System.Windows.Controls.ScrollViewer])) {
                    $scrollViewer = $scrollViewer.Parent
                }

                # Forward Page Up and Page Down events
                if ($scrollViewer) {
                    switch ($e.Key.ToString()) {
                        "PageUp" {  # Page Up
                            $scrollViewer.ScrollToVerticalOffset($scrollViewer.VerticalOffset - $scrollViewer.ViewportHeight)
                            $e.Handled = $true
                        }
                        "Next" {  # Page Down
                            $scrollViewer.ScrollToVerticalOffset($scrollViewer.VerticalOffset + $scrollViewer.ViewportHeight)
                            $e.Handled = $true
                        }
                    }
                }
            })
        }
    } else {
        Write-DebugLog -Message "Control '$($element.WPFName)' not found" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    }
}


function script:Invoke-ListBoxProcessing {
    param($element, $Window)

    Write-DebugLog -Message "Invoke-ListBoxProcessing" -Level 3 -LogFileName $($script:DrawGUIID + '.log')


    $control = $Window.FindName($element.WPFName)

    if ($control) {
        switch -Wildcard ($element.Properties.key) {
            'Text' {
                $control.SelectedItems.Clear()

                $($element.Properties | Where-Object { $_.Key -eq 'Text' }).Value | ForEach-Object {
                    $SelectedItems = $_
                    $index = $null

                    $items = $($element.Properties | Where-Object { $_.Key -eq 'Items' }).Value
                    $index = $items.IndexOf($($items | Where-Object { $_ -match [regex]::Escape($SelectedItems.Trim()) } | Select-Object -First 1))

                    if($index -ge 0) {
                        $control.SelectedItems.Add($control.Items[$index])
                    }
                }
            }
            'Events' {
                $events = $($element.Properties | Where-Object { $_.Key -eq 'Events' }).Value
                foreach ($eventName in $events.Keys) {
                    $eventScript = [System.Management.Automation.ScriptBlock]::Create($events[$eventName])
                    $control."add_$eventName"($eventScript)
                }
            }
            'Check' {
                Add-CheckHandler $control $($element.Properties | Where-Object { $_.Key -eq 'check' }).Value
            }
        }

    } else {
        Write-DebugLog -Message "Control '$($element.WPFName)' not found" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    }
}

function script:Invoke-OpenFileProcessing {
    param ($element, $Window)

    Write-DebugLog -Message "Starting OpenFile Processing" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

    $textBox = $Window.FindName($($element.WPFName))
    $button = $Window.FindName("OpenFile_$($element.WPFName)")

    $openFileElement = [PSCustomObject]@{
        Filter = $($element.Properties | Where-Object { $_.Key -eq 'Filter' }).Value ?? "All types (*.*)|*.*"
        InitialDirectory = $($element.Properties | Where-Object { $_.Key -eq 'InitialDirectory' }).Value ?? $env:USERPROFILE
    }

    Write-DebugLog -Message "Adding Click event to Button" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
    $button.add_Click([System.Management.Automation.ScriptBlock]::Create('
    param($sender, $e)

    $FileDialog = New-Object System.Windows.Forms.OpenFileDialog
    $FileDialog.Multiselect = $false
    $FileDialog.Filter = "' + $openFileElement.Filter + '"
    $FileDialog.InitialDirectory = "' + $openFileElement.InitialDirectory + '"

    $result = $FileDialog.ShowDialog()

    if ($result -eq "OK") {
        $textBox = $DrawGuiWindow.FindName($sender.Name.replace("OpenFile_",$null))

        $textBox.Text = $FileDialog.FileName
        #Write-Host "File selected: $($FileDialog.FileName)"
    }
'))

    if ($element.Properties.key -contains 'Text') {
        $textBox.text = $($element.Properties | Where-Object { $_.Key -eq 'Text' }).Value
    }

    if ($element.Properties.key -contains 'check') {
        Write-DebugLog -Message "Adding Check Handler to TextBox" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
        Add-CheckHandler $textBox $($element.Properties | Where-Object { $_.Key -eq 'check' }).Value
    }

    Write-DebugLog -Message "Finished OpenFile Processing" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
}

function script:Add-ComboBoxIconPreview {
    <# IconPreview ComboBox: the preview Border next to it shows the icon of the typed or selected value #>
    param ($Element, $Window)
    $combo = $Window.FindName($Element.WPFName)
    $preview = $Window.FindName("$($Element.WPFName)_Preview")
    if ($null -eq $combo -or $null -eq $preview) { return }
    $combo.Tag = $preview
    $render = {
        param($sender, $e)
        try {
            $target = $sender.Tag
            if ($null -eq $target) { return }
            $xaml = New-PowerControlIconXaml -Icon ([string]$sender.Text).Trim() -Size 20 -Margin '0'
            $target.Child = if ($xaml) { [Windows.Markup.XamlReader]::Parse("<Grid xmlns=`"http://schemas.microsoft.com/winfx/2006/xaml/presentation`" xmlns:x=`"http://schemas.microsoft.com/winfx/2006/xaml`">$xaml</Grid>") } else { $null }
        }
        catch { Write-DebugLog -Message "Icon preview failed: $_" -Level 2 -LogFileName $($script:DrawGUIID + '.log') }
    }
    $combo.Add_SelectionChanged($render)
    $combo.AddHandler([System.Windows.Controls.Primitives.TextBoxBase]::TextChangedEvent, [System.Windows.Controls.TextChangedEventHandler]$render)
    & $render $combo $null
}

function script:Add-CheckHandler {
    param ($control, $checkScript)

    Write-DebugLog -Message "Adding check handler to control: $($control.Name)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

    $control.add_LostFocus([System.Management.Automation.ScriptBlock]::Create('
        param($sender, $e)
        try {
            if ($null -eq $sender) { throw "Sender is null" }
            $result = Invoke-Command -ScriptBlock {' + $checkScript + '} -ArgumentList $sender, $e
            $sender.BorderBrush = if ($result -eq $true) { "#FFABADB3" } else { "#FFF92200" }

            Write-DebugLog -Message "Check result for $($sender.Name): $result" -Level 3 -LogFileName $($script:DrawGUIID + ".log")
        } catch {
            Write-DebugLog -Message "Error in check script for $($sender.Name): $_" -Level 1 -LogFileName $($script:DrawGUIID + ".log")
            Write-DebugLog -Message "Stack Trace: $($_.ScriptStackTrace)" -Level 1 -LogFileName $($script:DrawGUIID + ".log")
            $sender.BorderBrush = "#FFF92200"
        }
'))
}

function script:Test-FieldChecks {
    param ($DrawGuiWindow)

    Write-DebugLog -Message "Starting field checks" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    #$failedChecks = 0

    foreach($element in $script:WPFCollector){
        if ($element.Properties.key -contains 'check') {
            $control = $DrawGuiWindow.FindName($element.WPFName)

            if ($null -ne $control) {
                try {
                    $result = Invoke-Command -ScriptBlock ([ScriptBlock]::Create('param($sender, $e);' + $($element.Properties | Where-Object { $_.Key -eq 'check' }).Value)) -ArgumentList $control
                    $control.BorderBrush = if ($result -eq $true) { "#FFABADB3" } else { "#FFF92200"; $script:failedChecks += $element.WPFName }
                    Write-DebugLog -Message "Check result for $($control.Name): $result" -Level 3 -LogFileName $($script:DrawGUIID + '.log')
                } catch {
                    Write-DebugLog -Message "Error in check script for $($control.Name): $_" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
                    Write-DebugLog -Message "Stack Trace: $($_.ScriptStackTrace)" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
                    $control.BorderBrush = "#FFF92200"
                    $script:failedChecks += $element.WPFName
                }
            }
        }
    }   

    Write-DebugLog -Message "Field checks completed. Failed checks: $($script:failedChecks.count)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
}

function script:Show-PCtrlGUI {
    [CmdletBinding()]
    param (
        [Parameter(Mandatory=$true, ValueFromPipelineByPropertyName=$true)]
        [System.Collections.Hashtable]
        $GUItable
    )

    Write-DebugLog -Message "Starting Show-PCtrlGUI function" -Level 1 -LogFileName $($script:DrawGUIID + '.log')

    $xamlBuilder = [System.Text.StringBuilder]::new()

    $windowTitle = $GUItable['window']['title'] ? $GUItable['window']['title'].Replace('<','&lt;').Replace('>','&gt;') : 'PCtrlWindow'
    $xamlBuilder.AppendFormat("<Window Title=`"{0}`" SizeToContent=`"WidthAndHeight`" WindowStartupLocation=`"CenterScreen`" Topmost=`"True`" ", $windowTitle) | Out-Null
    # the dialog must fit into the working area (taskbar excluded): with the full screen height as limit a long
    # script pushed the button row behind the taskbar and "Save" could not be reached
    $workArea = [System.Windows.SystemParameters]::WorkArea
    $script:DrawGuiMaxEditorHeight = [int][Math]::Max(250, [Math]::Min(800, $workArea.Height * 0.55))
    # decided once per dialog: dark editor palette (theme Dark, setting CodeEditorColors not 'Light')
    $themeForEditor = if ($PowerControl.General.ThemeMode) { $PowerControl.General.ThemeMode } else { $PowerControl.General.Theme }
    if ($themeForEditor -eq 'System' -and (Get-Command Get-PowerControlEffectiveTheme -ErrorAction SilentlyContinue)) { $themeForEditor = Get-PowerControlEffectiveTheme -Theme 'System' }
    $script:DrawGuiEditorDark = Test-DrawGuiEditorDark -EffectiveTheme ([string]$themeForEditor)
    $xamlBuilder.AppendFormat("MaxHeight=`"{0}`" MaxWidth=`"{1}`" ", [int]($workArea.Height - 24), [int]($workArea.Width - 24)) | Out-Null

    $isClassicTheme = (-not $PowerControl.General.Theme) -or ($PowerControl.General.Theme -eq 'Classic')
    $minWidth = ($GUItable['window']['MinWidth'] -gt 0) ? $GUItable['window']['MinWidth'] : $(if ($isClassicTheme) { 300 } else { 440 })
    $xamlBuilder.AppendFormat("MinWidth=`"{0}`" ", $minWidth) | Out-Null
    # Fluent buttons need 32 px; the classic 20 px clip their text
    $buttonSize = if ($isClassicTheme) { 'MinWidth="45" Height="20"' } else { 'MinWidth="90" MinHeight="32" Padding="12,4"' }

    if ($GUItable['window']['Width'] -gt 0) {
        $xamlBuilder.AppendFormat("Width=`"{0}`"", $GUItable['window']['Width']) | Out-Null
    }

    if(Test-Path $($Global:PowerControl.General.CurrentPath  + '\dll\ICSharpCode.AvalonEdit.dll')) {
        Add-Type -Path $($Global:PowerControl.General.CurrentPath  + '\dll\ICSharpCode.AvalonEdit.dll')
    }
    else {
        Write-DebugLog -Message "Avalon DLL not found: $($Global:PowerControl.General.CurrentPath  + '\dll\ICSharpCode.AvalonEdit.dll')" -Level 2 -LogFileName 'DrawGUI-e7670e8344194a828558f726.log'
    }

    $xamlBuilder.Append(' xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"') | Out-Null
    $xamlBuilder.Append(' xmlns:avalon="http://icsharpcode.net/sharpdevelop/avalonedit"') | Out-Null
    $xamlBuilder.Append(' xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">') | Out-Null
    $xamlBuilder.Append("`n <ScrollViewer VerticalScrollBarVisibility=`"Auto`" HorizontalScrollBarVisibility=`"Auto`">") | Out-Null
    $xamlBuilder.Append("`n <Grid Margin=`"5`">") | Out-Null

    $description = $GUItable['window']['description'] ? $GUItable['window']['description'].Replace('<','&lt;').Replace('>','&gt;') : ''
    if($description.Trim().Length -gt 0){
        $xamlBuilder.AppendFormat("`n    <TextBlock Margin=`"5`">{0}</TextBlock>", $description) | Out-Null
        $xamlBuilder.Append("`n    <StackPanel Margin=`"0,5,0,0`">") | Out-Null

        $gridName = $GUItable['window']['GridName'] ? $GUItable['window']['GridName'] : 'PCtrlGrid'
        $xamlBuilder.AppendFormat("`n        <Grid Name=`"{0}`" Margin=`"0,15,0,0`" VerticalAlignment=`"Top`">", $gridName) | Out-Null
    }
    else {
        $xamlBuilder.Append("`n    <StackPanel Margin=`"0,0,0,0`">") | Out-Null

        $gridName = $GUItable['window']['GridName'] ? $GUItable['window']['GridName'] : 'PCtrlGrid'
        $xamlBuilder.AppendFormat("`n        <Grid Name=`"{0}`" Margin=`"0,0,0,0`" VerticalAlignment=`"Top`">", $gridName) | Out-Null
    }

    $xamlBuilder.Append(@"
`n<Grid.ColumnDefinitions>
      <ColumnDefinition Width=`"auto`"/>
      <ColumnDefinition Width=`"*`"/>
  </Grid.ColumnDefinitions>
  <Grid.RowDefinitions>
"@) | Out-Null

    $rowDefinitions = (0..($GUItable['dialog'].Count-1)).ForEach({ "`n              <RowDefinition Height=`"Auto`"/>" })
    $xamlBuilder.Append($rowDefinitions -join '') | Out-Null
    $xamlBuilder.Append("`n          </Grid.RowDefinitions>") | Out-Null

    $script:controlCounter = 0
    $script:WPFCollector = @()

    $counter = 0

    Write-DebugLog -Message "Processing dialog items" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    foreach ($item in $GUItable['dialog'].GetEnumerator() | Sort-Object @{e={$_.key -as [int]}}) {
        if ($item.value['Label']) {
            $xamlBuilder.AppendFormat("`n    <TextBlock Grid.Column=`"0`" Margin=`"5,5,12,5`" HorizontalAlignment=`"Left`" VerticalAlignment=`"Center`" Grid.Row=`"{0}`">{1}</TextBlock> ", $counter, [System.Security.SecurityElement]::Escape([string]$item.value['Label'])) | Out-Null
        }

        Add-WPFElement -xamlBuilder $xamlBuilder -element $item.value -row $counter -column 1

        $counter++
    }

    $xamlBuilder.Append("`n       </Grid>") | Out-Null
    $xamlBuilder.Append("`n       <UniformGrid Columns=`"2`" Grid.Row=`"1`">") | Out-Null

    Write-DebugLog -Message "Processing action buttons" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    if ($GUItable['actionButtons']) {
        foreach ($button in $GUItable['actionButtons'].GetEnumerator() | Sort-Object @{e={$_.key -as [int]}}) {
            $xamlBuilder.AppendFormat("`n           <Button Name=`"{0}`"", $button.value['Name']) | Out-Null
            if ($button.value['isDefault']) {
                $xamlBuilder.Append(' IsDefault="True"') | Out-Null
            }
            $xamlBuilder.AppendFormat(" $buttonSize Margin=`"5`">{0}</Button> ", $button.value['Label'].Replace('<','&lt;').Replace('>','&gt;')) | Out-Null
        }
    }
    else {
        $xamlBuilder.Append("`n           <Button Name=`"ButtonOk`" IsDefault=`"True`" $buttonSize Margin=`"5`">Ok</Button> ") | Out-Null
    }

    $xamlBuilder.Append(@"
`n</UniformGrid>
  </StackPanel>
 </Grid>
 </ScrollViewer>
</Window>
"@) | Out-Null

    $xaml = $xamlBuilder.ToString()

    Write-DebugLog -Message "XAML generated" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    Write-DebugLog -Message $xaml -Level 2 -LogFileName $($script:DrawGUIID + '.log')

    Write-DebugLog -Message "Creating window" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    $DrawGuiWindow = Convert-XAMLtoWindow -XAML $xaml 
    Write-DebugLog -Message "Window created" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

    # dialogs follow the main window's theme setting (Light / Dark / System)
    $dialogTheme = if ($PowerControl.General.ThemeMode) { $PowerControl.General.ThemeMode } else { $PowerControl.General.Theme }
    if ($dialogTheme -and $dialogTheme -ne 'Classic') {
        try { $DrawGuiWindow.ThemeMode = [System.Windows.ThemeMode]::($dialogTheme) } catch { }
    }
    # inline Lucide icons (icon picker) stroke with this brush; the dialog has no access to the main window's resources
    $effectiveTheme = $dialogTheme
    if ($effectiveTheme -eq 'System' -and (Get-Command Get-PowerControlEffectiveTheme -ErrorAction SilentlyContinue)) { $effectiveTheme = Get-PowerControlEffectiveTheme -Theme 'System' }
    $DrawGuiWindow.Resources['PowerControlIconBrush'] = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.ColorConverter]::ConvertFromString($(if ($effectiveTheme -eq 'Dark') { '#FFE6E6E6' } else { '#FF1F1F1F' })))
    # code editor (AvalonEdit) colors; the control has no Fluent template and would stay white in the dark theme.
    # Setting CodeEditorColors = 'Light' keeps the white editor (with the standard syntax colors) in the dark theme.
    $editorDark = Test-DrawGuiEditorDark -EffectiveTheme $effectiveTheme
    $DrawGuiWindow.Resources['PowerControlEditorBackgroundBrush'] = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.ColorConverter]::ConvertFromString($(if ($editorDark) { '#FF1E1E1E' } else { '#FFFFFFFF' })))
    $DrawGuiWindow.Resources['PowerControlEditorForegroundBrush'] = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.ColorConverter]::ConvertFromString($(if ($editorDark) { '#FFE6E6E6' } else { '#FF1F1F1F' })))

    $DrawGuiWindow.add_Loaded({
        try {
            Write-DebugLog -Message "Window Loaded event triggered" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
            # bring the dialog in front of the main window and give it the keyboard focus (opened from another runspace)
            [void]$DrawGuiWindow.Activate()
            if ($null -ne $WPFCollector) {
                Write-DebugLog -Message "Starting to process GUI elements" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
                Invoke-GUIElementProcessing -Elements $WPFCollector -ParentControl $DrawGuiWindow
                Write-DebugLog -Message "Finished processing GUI elements" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

                foreach($element in $script:WPFCollector){
                    if ($element.Properties.key -contains 'focus') {
                        $control = $DrawGuiWindow.FindName($element.WPFName)

                        if ($null -ne $control) {    
                            $control.Focus()
                            if($null -ne $control.GetType().GetMethod("SelectAll")){
                                $control.SelectAll()
                            }
                            Write-DebugLog -Message "Focus set on $($control.Name)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
                        }
                    }
                }

            } else {
                Write-DebugLog -Message "Invalid or null 'dialog' structure in GUItable. GUI elements may not be processed correctly." -Level 2 -LogFileName $($script:DrawGUIID + '.log')
            }

            $getDialog = $DrawGuiWindow.FindName($GUItable['window']['GridName'] ?? 'PCtrlGrid')

            $getDialog.Children.Where({ $_.Name.Length -gt 0 }).ForEach({
                $_.add_KeyDown({
                    if ($_.Key -eq 'Escape'){$DrawGuiWindow.DialogResult = $false}elseif ($_.Key -eq 'Enter'){$DrawGuiWindow.DialogResult = $true}
                })
            })
        }
        catch {
            Write-DebugLog -Message "An error occurred while processing GUI elements: $_" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
            Write-DebugLog -Message "Stack Trace: $($_.ScriptStackTrace)" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
            $DrawGuiWindow.Close()
        }
    })

    Write-DebugLog -Message "Setting up FieldChecks" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
    $FieldChecks = {
        Write-DebugLog -Message "Running FieldChecks" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        $script:failedChecks = @()
        Test-FieldChecks -DrawGuiWindow $DrawGuiWindow

        Write-DebugLog -Message "Failed checks: $($script:failedChecks.count)" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        if ($script:failedChecks.count -eq 0) {
            $DrawGuiWindow.DialogResult = $true
        }
        else {
            $errorMessage = "The following fields do not conform:`n`n"
            foreach ($failedCheck in $script:failedChecks) {
                $errorMessage += "- $failedCheck`n"
            }

            [System.Windows.MessageBox]::Show($errorMessage, "Validation Error", [System.Windows.MessageBoxButton]::OK, [System.Windows.MessageBoxImage]::Error)
        }
    }

    if($null -ne $GUItable['actionButtons']) {  
        $GUItable['actionButtons'].Values.ForEach({
            if(($null -ne $_.Code) -and ($_.Code -is [System.Management.Automation.ScriptBlock])) {
                if($_.Code -like '*$DrawGuiWindow*') {
                    $DrawGuiWindow.$($_.Name).add_Click($_.Code) 
                }
                else {
                    if($null -ne $GUItable['OnResult']) {
                        $DrawGuiWindow.$($_.Name).add_Click([System.Management.Automation.ScriptBlock]::Create($([string]$FieldChecks) + ';' + $([string]$_.Code)))
                    }
                    else {
                        $DrawGuiWindow.$($_.Name).add_Click([System.Management.Automation.ScriptBlock]::Create('$DrawGuiWindow.DialogResult = $false ; ' + $_.Code))
                    }
                }
            }
            else {
                $DrawGuiWindow.$($_.Name).add_Click([System.Management.Automation.ScriptBlock]::Create($FieldChecks))
            }
        })
    }
    else {
        $DrawGuiWindow.ButtonOk.add_Click([System.Management.Automation.ScriptBlock]::Create($FieldChecks))
    } 

    Write-DebugLog -Message "Showing WPF Window" -Level 2 -LogFileName $($script:DrawGUIID + '.log')

    Show-WPFWindow -Window $DrawGuiWindow | Out-Null

    $script:GUIResults = @{}

    if ($DrawGuiWindow.DialogResult -eq $true) {
        Write-DebugLog -Message "Dialog result is true, processing results" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
        $mainGrid = $DrawGuiWindow.FindName($GUItable['window']['GridName'] ?? 'PCtrlGrid')

        if ($null -ne $mainGrid) {
            $rawResults = Get-ControlValues -Container $DrawGuiWindow
            $script:GUIResults = ConvertTo-NormalizedGuiResults -GuiResults $rawResults
        }

        if ($script:PowerControlDryRun) {
            # "Dry run": the dialog values become rows, OnResult (the real work) is skipped
            Write-DebugLog -Message "Dry run: OnResult skipped, $($script:GUIResults.Count) value(s) reported" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
            foreach ($key in @($script:GUIResults.Keys | Sort-Object)) {
                $value = $script:GUIResults[$key]
                $text = if ($value -is [System.Security.SecureString]) { '********' } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } elseif ($value -is [array]) { ($value | ForEach-Object { [string]$_ }) -join ', ' } else { [string]$value }
                $Script:PowerControlItem_Output += [PSCustomObject]@{ Dialog = [string]$GUItable['window']['title']; Field = $key; Value = $text; Type = $(if ($null -ne $value) { $value.GetType().Name } else { '' }) }
            }
        }
        elseif ($GUItable['OnResult'] -is [System.Management.Automation.ScriptBlock]) {
            Write-DebugLog -Message "Executing OnResult script block" -Level 2 -LogFileName $($script:DrawGUIID + '.log')
            & $GUItable['OnResult']
            #Invoke-Command $GUItable['OnResult'] -NoNewScope
        }
    }

    Write-DebugLog -Message "Show-PCtrlGUI function script:completed" -Level 1 -LogFileName $($script:DrawGUIID + '.log')
}

			function script:ConvertTo-ShortString {
    [CmdletBinding()]
    param (
        [Parameter(Position = 0, ValueFromPipeline=$true, ValueFromPipelineByPropertyName=$true)]
        [string] $String,

        [Parameter(Position = 1)]
        [Alias('StartAt')]
        [int] $MinLength,

        [Parameter(Position = 2)]
        [Alias('EndAt')]
        [int] $MaxLength = 255,

        [Parameter(Position = 3)]
        [Alias('CustomString')]
        [string] $Separator = "`n"
    )

    begin {
        $regexPattern = [regex]::new("^(.{1,$MinLength})(?=\b([,()])?)")
    }

    process {
        if (($MaxLength -le 0) -or ($String.Length -eq 0)) {
            return $String
        }

        if ($String.Length -le $MinLength) {
            return $String
        }

        $match = $regexPattern.Match($String)
        $remainingString = $String.Substring($match.Length)

        if ($remainingString.Length -gt $MinLength) {
            $shortenedRemainder = ConvertTo-ShortString -String $remainingString -MinLength $MinLength -MaxLength ($MaxLength - $MinLength) -Separator $Separator
            return "$($match.Value)$Separator$shortenedRemainder".Trim()
        } else {
            return "$($match.Value)$Separator$remainingString".Trim()
        }
    }
}

$ACTION_PowerControlItem = $($Global:PowerControl.History.where({($_.id -ceq $Global:PowerControl.ActiveMenu.ID) -and ($_.TimeStamp -eq $Global:PowerControl.ActiveMenu.TimeStamp)}))

$itemsToFind = @{}
$PowerControlItem_Children = $ACTION_PowerControlItem.Children  | Sort-Object Timestamp -Descending 
$PowerControlItem_Children[1..$ACTION_PowerControlItem.Children.count] | ForEach-Object {
    $key = "$($_.id)_$($_.Timestamp)"
    $itemsToFind[$key] = $true
}

$ACTION_PowerControlItem = @($PowerControl.History | Where-Object {
    $key = "$($_.id)_$($_.Timestamp)"
    ($itemsToFind.ContainsKey($key)) -and ($_.Output.count -gt 0)
}) | Select-Object -First 1

$script:SelectedEntries = $ACTION_PowerControlItem.SelectedEntries

# Uses the same resolver as the engine (Get-ActionSequence) and walks the result the way
# Invoke-ActionScript executes it: PrevActions by priority (desc), the element, NextActions by priority (desc).
$script:TimelineSort = 0

function Add-TimelineRows {
    param([hashtable]$Node, [string]$Owner, [string]$Time, [int]$Depth, [string]$SourceID)

    if ($Node.PrevAction) {
        foreach ($prev in ($Node.PrevAction.GetEnumerator() | Sort-Object { [int]$_.Value.Priority } -Descending)) {
            Add-TimelineRows -Node $prev.Value -Owner $Node.Label -Time 'PrevAction' -Depth ($Depth + 1) -SourceID $SourceID
        }
    }

    $script:TimelineSort++
    $label = if ($Node.Label) { $Node.Label } else { "$($Node.ID) (missing in engine)" }
    $Script:PowerControlItem_Output += [PSCustomObject]@{
        Sort      = $script:TimelineSort
        Step      = ('    ' * $Depth) + $label
        Time      = $Time
        Priority  = $(if ($null -ne $Node.Priority) { $Node.Priority } else { '' })
        Owner     = $Owner
        Apartment = $(if ($Node.ApartmentState) { $Node.ApartmentState } else { 'MTA' })
        HasScript = -not [string]::IsNullOrWhiteSpace($Node.ScriptBlock)
        ID        = $Node.ID
        SourceID  = $SourceID
    }

    if ($Node.NextAction) {
        foreach ($next in ($Node.NextAction.GetEnumerator() | Sort-Object { [int]$_.Value.Priority } -Descending)) {
            Add-TimelineRows -Node $next.Value -Owner $Node.Label -Time 'NextAction' -Depth ($Depth + 1) -SourceID $SourceID
        }
    }
}

@($script:SelectedEntries) | Where-Object { $_.id } | ForEach-Object {
    $sequence = Get-ActionSequence -ID $_.id
    foreach ($root in $sequence.Values) {
        Add-TimelineRows -Node $root -Owner '' -Time 'Main' -Depth 0 -SourceID $_.id
    }
}

$Script:PowerControlItem_ExcludeProperty = @('SourceID')

# Stop Thread
$script:SelectedEntries | ForEach-Object {
    $item = $_
    $private:PowerControlItem = $PowerControl.History | Where-Object {($_.id -ceq $item.ID) -and ($_.TimeStamp -ceq $item.Timestamp)}
    Stop-PowerControlThreads -HistoryItem $private:PowerControlItem
}

$script:SelectedEntries | ForEach-Object {
    $item = $_
    $private:PowerControlItem = $PowerControl.History | Where-Object {($_.id -ceq $item.ID) -and ($_.TimeStamp -ceq $item.Timestamp)}

    Write-DebugLog -Message "How big :$($private:PowerControlItem.Output.count)" -Level 2 -LogFileName 'PostScript.log' 
    $Script:PowerControlItem_Output += $private:PowerControlItem.Output
}

$script:SelectedEntries | ForEach-Object {
    $item = $_
    $private:PowerControlItem = $PowerControl.History | Where-Object {($_.id -ceq $item.ID) -and ($_.TimeStamp -ceq $item.Timestamp)}
    $private:PowerControlItem.Pinned = $true
}

$asText = { param($value) if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value } }
$GUItable = @{
  'window' = @{ 'title' = 'Repeat job'; 'description' = 'The job runs again on its own entry after every interval (checked once a second). A repeating job is pinned so it is not cleaned up. Previous outputs stay available via Compare with... and Previous runs...' }
  'dialog' = @{
    0 = @{ 'Label' = 'Interval (e.g. 30 s, 5 min, 1 h; 0 = off)'; 'ComboBox' = @{ 'Name' = 'Interval'; 'IsEditable' = $true; 'Text' = '5 min'; 'Focus' = $true; 'Elements' = @('0 (off)', '10 s', '30 s', '1 min', '5 min', '15 min', '30 min', '1 h') } }
    1 = @{ 'CheckBox' = @{ 'Name' = 'Notify'; 'Text' = 'Notify (banner + tray) when the output differs from the previous run'; 'IsChecked' = $true } }
    2 = @{ 'Label' = 'Previous outputs to keep'; 'TextBox' = @{ 'Name' = 'Keep'; 'Text' = '10'; 'check' = { $sender.Text -match '^\d{1,3}$' } } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Apply'; 'Name' = 'Apply'; 'isDefault' = $true } }
  'OnResult' = {
    $text = ((& $asText $GUIResults.Interval) -replace ',', '.').Trim().ToLowerInvariant()
    $seconds = 0
    if ($text -notmatch '^0\b') {
        if ($text -match '^(\d+(?:\.\d+)?)\s*(s|sec|secs|second|seconds|m|min|mins|minute|minutes|h|hr|hrs|hour|hours)?$') {
            $value = [double]$Matches[1]
            $seconds = switch -Regex ("$($Matches[2])") { '^s' { $value } '^h' { $value * 3600 } default { $value * 60 } }
        }
        else { throw "Interval '$text' not understood; examples: 30 s, 5 min, 1 h, 0" }
    }
    $seconds = [int][math]::Round($seconds)
    if ($seconds -gt 0 -and $seconds -lt 2) { $seconds = 2 }
    foreach ($entry in @($script:SelectedEntries)) {
        $item = $PowerControl.History | Where-Object { ($_.ID -ceq $entry.ID) -and ("$($_.TimeStamp)" -eq "$($entry.Timestamp)") } | Select-Object -First 1
        if ($null -eq $item) { continue }
        $item | Add-Member -NotePropertyName Repeat -NotePropertyValue $seconds -Force
        $item | Add-Member -NotePropertyName RepeatNext -NotePropertyValue ((Get-Date).AddSeconds($seconds)) -Force
        $item | Add-Member -NotePropertyName RepeatNotify -NotePropertyValue ([bool]$GUIResults.Notify) -Force
        $item | Add-Member -NotePropertyName RepeatHistory -NotePropertyValue ([int]$GUIResults.Keep) -Force
        if ($seconds -gt 0) { $item.Pinned = $true }
        Write-DebugLog -Message "Repeat for $($item.Name): every $seconds s, notify=$([bool]$GUIResults.Notify), keep=$([int]$GUIResults.Keep)" -Level 1 -LogFileName 'UI.log'
    }
  }
}
Show-PCtrlGUI -GUItable $GUItable

$entry = @($script:SelectedEntries)[0]
if ($null -eq $entry) { throw 'No job selected.' }
[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try {
    $jobA = $PowerControl.History | Where-Object { ($_.ID -ceq $entry.ID) -and ("$($_.TimeStamp)" -eq "$($entry.Timestamp)") } | Select-Object -First 1
    $others = @($PowerControl.History | Where-Object { $_.NodeType -notin $PowerControl.General.TransientNodeTypes -and $null -ne $_.Output -and @($_.Output).Count -gt 0 -and -not [object]::ReferenceEquals($_, $jobA) })
}
finally { [System.Threading.Monitor]::Exit($PowerControl.HistoryLock) }
if ($null -eq $jobA -or $null -eq $jobA.Output -or @($jobA.Output).Count -eq 0) { throw 'The selected job has no output to compare.' }
$rerunLabel = "(run '$($jobA.Name)' again now and compare)"
$labels = @($rerunLabel); $byLabel = @{}; $historyByLabel = @{}
# previous runs kept by "Repeat..." (OutputHistory, newest first)
if ($jobA.PSObject.Properties['OutputHistory']) {
    foreach ($snapshot in @($jobA.OutputHistory)) {
        $label = "previous run $(([datetime]$snapshot.Time).ToString('HH:mm:ss')) ($(@($snapshot.Rows).Count) rows)"
        if ($historyByLabel.ContainsKey($label)) { continue }
        $labels += $label; $historyByLabel[$label] = $snapshot
    }
}
foreach ($job in $others) {
    $stamp = try { [DateTimeOffset]::FromUnixTimeSeconds([long][double]$job.Timestamp).ToLocalTime().ToString('HH:mm:ss') } catch { "$($job.Timestamp)" }
    $label = (("$($job.Name) ($stamp, $(@($job.Output).Count) rows)") -replace '\s+', ' ').Trim()
    if ($byLabel.ContainsKey($label)) { continue }
    $labels += $label; $byLabel[$label] = $job
}
$asText = { param($value) $text = if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value }; ($text -replace '\s+', ' ').Trim() }
$keyChoices = @('(row position)') + @($jobA.Output[0].PSObject.Properties.Name)
$GUItable = @{
  'window' = @{ 'title' = "Compare '$($jobA.Name)' with..."; 'description' = 'An existing job, a previous run of this job, or the same menu run again right now (its dialog opens again if it has one). Table: rows paired by the key column, changed cells as "old → new". The result opens as a new job.' }
  'dialog' = @{
    0 = @{ 'Label' = 'Compare with'; 'ComboBox' = @{ 'Name' = 'Other'; 'IsEditable' = $false; 'Text' = $labels[0]; 'Elements' = $labels } }
    1 = @{ 'Label' = 'Layout'; 'ComboBox' = @{ 'Name' = 'Layout'; 'IsEditable' = $false; 'Text' = 'Table (changed cells as old → new)'; 'Elements' = @('Table (changed cells as old → new)', 'Lines (text diff)') } }
    2 = @{ 'Label' = 'Key column (table layout)'; 'ComboBox' = @{ 'Name' = 'KeyColumn'; 'IsEditable' = $true; 'Text' = $(if ($keyChoices.Count -gt 1) { $keyChoices[1] } else { $keyChoices[0] }); 'Elements' = $keyChoices } }
    3 = @{ 'CheckBox' = @{ 'Name' = 'ShowSummary'; 'Text' = 'Summary row'; 'IsChecked' = $true } }
    4 = @{ 'CheckBox' = @{ 'Name' = 'ShowAdded'; 'Text' = 'added (only in the new side) and changed'; 'IsChecked' = $true } }
    5 = @{ 'CheckBox' = @{ 'Name' = 'ShowRemoved'; 'Text' = 'removed (only in the old side) and changed'; 'IsChecked' = $true } }
    6 = @{ 'CheckBox' = @{ 'Name' = 'ShowEqual'; 'Text' = 'equal (in both)'; 'IsChecked' = $false } }
    7 = @{ 'CheckBox' = @{ 'Name' = 'ShowContext'; 'Text' = 'lines layout: two equal rows of context around each difference'; 'IsChecked' = $true } }
  }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Compare'; 'Name' = 'Compare'; 'isDefault' = $true } }
  'OnResult' = {
    $choice = & $asText $GUIResults.Other
    $keyText = & $asText $GUIResults.KeyColumn
    $request = @{ AKey = "$($jobA.ID)|$($jobA.Timestamp)"; BKey = $null; RerunId = $null; BRows = $null; BName = $null; Layout = (& $asText $GUIResults.Layout); KeyColumn = $(if ($keyText -like '(row position)*') { '' } else { $keyText }); Filters = @{ Summary = [bool]$GUIResults.ShowSummary; Equal = [bool]$GUIResults.ShowEqual; Added = [bool]$GUIResults.ShowAdded; Removed = [bool]$GUIResults.ShowRemoved; Context = [bool]$GUIResults.ShowContext } }
    # the comparison runs as a new job; an unpinned job would be pruned before it is read, so pin the participants
    $jobA.Pinned = $true
    if ($choice -eq $rerunLabel) { $request.RerunId = [string]$jobA.ID }
    elseif ($historyByLabel.ContainsKey($choice)) { $request.BRows = @($historyByLabel[$choice].Rows); $request.BName = $choice }
    else {
        $jobB = $byLabel[$choice]
        if ($null -eq $jobB) { throw 'Select a job.' }
        $jobB.Pinned = $true
        $request.BKey = "$($jobB.ID)|$($jobB.Timestamp)"
    }
    $PowerControl.UI.PendingCompare = $request
    $PowerControl.UI.PendingRun = @{ ID = 'CompareOutputs-6071829304a5b6c7d8e9f0a1b2c3d4e5'; Entries = @() }
    Invoke-PowerControlUICommand -Name RunPending
  }
}
Show-PCtrlGUI -GUItable $GUItable

$entry = @($script:SelectedEntries)[0]
if ($null -eq $entry) { throw 'No job selected.' }
# not $item: OnResult runs inside Show-PCtrlGUI, whose own loop variables ($item, ...) would shadow it
$repeatJob = $PowerControl.History | Where-Object { ($_.ID -ceq $entry.ID) -and ("$($_.TimeStamp)" -eq "$($entry.Timestamp)") } | Select-Object -First 1
if ($null -eq $repeatJob -or -not $repeatJob.PSObject.Properties['OutputHistory'] -or @($repeatJob.OutputHistory).Count -eq 0) { throw 'No previous outputs kept for this job.' }
$labels = @(); $byLabel = @{}
foreach ($snapshot in @($repeatJob.OutputHistory)) {
    $label = "$(([datetime]$snapshot.Time).ToString('HH:mm:ss')) ($(@($snapshot.Rows).Count) rows)"
    if ($byLabel.ContainsKey($label)) { continue }
    $labels += $label; $byLabel[$label] = $snapshot
}
$asText = { param($value) $text = if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value }; ($text -replace '\s+', ' ').Trim() }
$GUItable = @{
  'window' = @{ 'title' = "Previous runs of '$($repeatJob.Name)'"; 'description' = 'The chosen output opens as a new job "Previous run" (compare it with the current one via Compare with...).' }
  'dialog' = @{ 0 = @{ 'Label' = 'Run'; 'ComboBox' = @{ 'Name' = 'Run'; 'IsEditable' = $false; 'Text' = $labels[0]; 'Elements' = $labels } } }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Show'; 'Name' = 'Show'; 'isDefault' = $true } }
  'OnResult' = {
    $chosen = $byLabel[(& $asText $GUIResults.Run)]
    if ($null -eq $chosen) { throw 'Select a run.' }
    $PowerControl.UI.PendingSnapshot = @{ Name = [string]$repeatJob.Name; Time = $chosen.Time; Rows = @($chosen.Rows) }
    $PowerControl.UI.PendingRun = @{ ID = 'ShowSnapshot-b5c6d7e8f9a0b1c2d3e4f5a6b7c8d9ea'; Entries = @() }
    Invoke-PowerControlUICommand -Name RunPending
  }
}
Show-PCtrlGUI -GUItable $GUItable

# same lists as the stars in the shell: settings FavoriteMenus (Menu, MenuBar) and FavoriteActions (Action)
$settings = $PowerControl.Settings
foreach ($item in @($script:SelectedEntries)) {
    $element = $PowerControl.JsonCache.PCtrlItems.where({ $_.id -eq $item.ID }, 'First')[0]
    if ($null -eq $element) { continue }
    $key = if ($element.type -eq 'Action') { 'FavoriteActions' } else { 'FavoriteMenus' }
    $current = @($settings[$key] | Where-Object { $_ })
    $settings[$key] = if ($current -contains [string]$element.id) { @($current | Where-Object { $_ -ne [string]$element.id }) } else { @($current) + @([string]$element.id) }
    Write-DebugLog -Message "Favourite toggled for $($element.id) ($key)" -Level 1 -LogFileName 'PowerControl.log'
}
Save-PowerControlSettings
Invoke-PowerControlUICommand -Name RefreshFavorites

# keep: running jobs, pinned jobs, the active menu and its active action (their output is on screen)
[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try {
    $activeMenu = $PowerControl.History.where({ ($_.id -ceq $PowerControl.ActiveMenu.ID) -and ("$($_.TimeStamp)" -eq "$($PowerControl.ActiveMenu.TimeStamp)") }, 'First')[0]
    $before = $PowerControl.History.Count

    # actions of pinned menus are the context of their tab and stay as well
    $protected = [System.Collections.Generic.HashSet[string]]::new()
    foreach ($menu in @($PowerControl.History)) {
        if ($menu.Pinned -eq $true -and $menu.NodeType -in 'Menu', 'MenuBar') { foreach ($child in @($menu.Children)) { if ($null -ne $child) { [void]$protected.Add("$($child.Id)_$($child.Timestamp)") } } }
    }

    $keep = @($PowerControl.History | Where-Object {
        $item = $_
        ($null -ne $item.Thread.Handle -and -not $item.Thread.Handle.IsCompleted) -or
        ($item.Pinned -eq $true) -or
        $protected.Contains("$($item.ID)_$($item.TimeStamp)") -or
        ($null -ne $activeMenu -and $item.ID -ceq $activeMenu.ID -and "$($item.TimeStamp)" -eq "$($activeMenu.TimeStamp)") -or
        ($null -ne $activeMenu -and $null -ne $activeMenu.ActiveAction -and $item.ID -ceq $activeMenu.ActiveAction.Id -and "$($item.TimeStamp)" -eq "$($activeMenu.ActiveAction.Timestamp)")
    })

    $PowerControl.History = [System.Collections.ArrayList]$keep
    Write-DebugLog -Message "Clear finished jobs: removed $($before - $keep.Count) of $before history items" -Level 1 -LogFileName 'PowerControl.log'
}
finally {
    [System.Threading.Monitor]::Exit($PowerControl.HistoryLock)
}

[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try {
    foreach ($item in @($PowerControl.History)) {
        if ($item.NodeType -in $PowerControl.General.TransientNodeTypes) { continue }
        $item.Pinned = $true
    }
}
finally { [System.Threading.Monitor]::Exit($PowerControl.HistoryLock) }

[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try { foreach ($item in @($PowerControl.History)) { if ($item.Pinned -eq $true) { $item.Pinned = $false } } }
finally { [System.Threading.Monitor]::Exit($PowerControl.HistoryLock) }

[System.Threading.Monitor]::Enter($PowerControl.HistoryLock)
try { $running = @($PowerControl.History | Where-Object { $_.NodeType -notin $PowerControl.General.TransientNodeTypes -and $null -ne $_.Thread.Handle -and -not $_.Thread.Handle.IsCompleted }) }
finally { [System.Threading.Monitor]::Exit($PowerControl.HistoryLock) }
foreach ($item in $running) { Stop-PowerControlThreads -HistoryItem $item }
Write-DebugLog -Message "Stop all jobs: $($running.Count) job(s) stopped" -Level 1 -LogFileName 'PowerControl.log'

# counterpart of "Pin it": the job is removed from the list again by the HistoryWatcher once it is
# finished and no longer the active action
$script:SelectedEntries | ForEach-Object {
    $item = $_
    $private:PowerControlItem = $PowerControl.History | Where-Object {($_.id -ceq $item.ID) -and ($_.TimeStamp -ceq $item.Timestamp)}
    if ($null -ne $private:PowerControlItem) { $private:PowerControlItem.Pinned = $false }
}

$data = $null

$elementID = $null


if($null -ne $Global:PowerControl.EventParams.sender.uid) {
    $elementID = $Global:PowerControl.EventParams.sender.uid
}
elseif($null -ne $SelectedEntries.id) {
    $elementID = $SelectedEntries.id
}

# rows without an element id (dry run values, "Received no results", comparison rows) cannot be edited
if ([string]::IsNullOrWhiteSpace("$elementID")) { throw 'Select an element row first (List all PCtrl Elements or KeyBindings), or right click an element in the navigation, the actions panel or the start page.' }

$data = Get-ElementByIdFromIndex -id $elementID

if($null -ne $data) {      

  $windowSettings = @{
      'title' = 'Edit element'
  }

  # Important tab elements
  $importantTabElements = @(
      @{
          'GroupBox' = @{
              'Header' = 'Basics'
              'Elements' = @(
                  @{
                      'TextBox' = @{
                          'Name' = 'ElementName'
                          'Text' = $data.PCtrl.Label
                          'check' = { $sender.Text.Length -gt 0 }
                      }
                  },
                  @{
                      'Label' = 'Type'
                      'ComboBox' = @{
                          'Name' = 'Type'
                          'IsEditable' = $false
                          'Text' = $data.PCtrl.type
                          'Elements' = @('Action', 'Menu', 'MenuBar','Thread','EditTreeView')
                      }
                      #IsEnabled
                  },
                  @{
                      'Label' = 'File'
                      'TextBox' = @{
                          'Name' = 'File'
                          'IsReadOnly' = $true
                          'ToolTip' = 'Engine file of this element. To move it, use Move element to file... on the List all / KeyBindings rows.'
                          'Text' = $($PowerControl.JsonCache.PCtrlItems.Where({ ($_.id -eq $elementID)})).file
                      }
                  }
              )
          }
      },
      @{
          'GroupBox' = @{
              'Header' = 'Script'
              'Elements' = @(
                  @{
                      'Label' = 'Multi-line; enter PowerShell code.'
                      'CodeEditor' = @{
                          'Name' = 'Script'
                          'Text' = $data.PCtrl.Script.'#cdata-section'
                          'MultiLine' = $true
                          # syntax check with the real parser before the element is saved (red border + message on failure)
                          'check' = { (Test-HereStringValidity -Script $sender.Text).IsValid }
                      }
                  }
              )
          }
      }
  )

  # Misc tab elements
  $miscTabElements = @(
      @{
          'GroupBox' = @{
              'Header' = 'Misc'
              'Elements' = @(
                  @{
                      'Label' = 'ID'
                      'TextBox' = @{
                          'Name' = 'ElementID'
                          'Text' = [string]$data.PCtrl.ID
                          'IsReadOnly' = $true
                          'ToolTip' = 'Fixed identifier of this element, used by PrevAction/NextAction, Children and bundles. Select and copy; it cannot be changed here.'
                      }
                  },
                  @{
                      'Label' = 'Description'
                      'TextBox' = @{
                          'Name' = 'Description'
                          'MultiLine' = $true
                      }
                  },
                  @{
                      'Label' = 'Icon'
                      'ComboBox' = @{
                          'Name' = 'Icon'
                          'IsEditable' = $true
                          'Text' = [string]$data.PCtrl.Icon
                          'Elements' = @(Get-ChildItem -Path (Join-Path $PowerControl.General.CurrentPath 'icons\lucide') -Filter '*.svg' | Sort-Object Name | ForEach-Object { 'lucide\' + $_.Name })
                          'ToolTip' = 'Pick a Lucide icon from icons\lucide or type a path relative to icons\'
                          'IconPreview' = $true
                      }
                  },
                  @{
                      'Label' = 'ToolTip'
                      'TextBox' = @{
                          'Name' = 'ToolTip'
                          'Text' = $data.PCtrl.ToolTip
                      }
                  }
              )
          }
      },
      @{
          'GroupBox' = @{
              'Header' = 'Display Condition'
              'Elements' = @(
                  @{
                      'Label' = 'Multi-line; enter PowerShell code.'
                      'CodeEditor' = @{
                          'Name' = 'DisplayCondition'
                          'MultiLine' = $true
                          'MinWidth'  = '500'
                          'MinHeight'  = '50'
                          'text' = $data.PCtrl.DisplayCondition.'#cdata-section'
                      }
                  },
                  @{
                      'Label' = 'Category:'
                      'TextBox' = @{
                          'Name' = 'Category'
                          'text' = $data.PCtrl.DisplayCondition.Categorie
                      }
                  },
                  @{
                      'Label' = 'Sort Order: e.g. 3'
                      'TextBox' = @{
                          'Name' = 'SortOrder'
                          'text' = $data.PCtrl.DisplayCondition.SortOrder
                          'check' = { if($sender.Text.Length -gt 0) {
                              try {[int]$sender.Text -is [int]}catch{$false}
                            }
                            else {
                              $true
                            }
                          }
                      }
                  }
              )
          }
      }
  )

  # Key Binding tab elements
  $keyBindingTabElements = @(
      @{
          'GroupBox' = @{
              'Header' = 'Key Binding'
              'Elements' = @(
                  @{
                      'Label' = 'Key'
                      'TextBox' = @{
                          'Name' = 'Key'
                          'Text' = $data.PCtrl.KeyBinding.key
                      }
                  },
                  @{
                      'Label' = 'Modifiers'
                      'ComboBox' = @{
                          'Name' = 'Modifiers'
                          'IsEditable' = $false
                          'Text' = $data.PCtrl.KeyBinding.Modifiers
                          'Elements' = @(
                              'None', 'Ctrl', 'Alt', 'Shift',
                              'Ctrl+Alt', 'Ctrl+Shift', 
                              'Alt+Shift', 'Ctrl+Alt+Shift'
                          )
                      }
                  }
              )
          }
      }
  )

  $ListBoxItems = @()

  $PowerControl.JsonCache.Pctrlitems | Sort-Object Label | Select-Object id, Label | ForEach-Object {
      $ListBoxItems += "$($_.Label) - $($_.id)"
  }   

  $WorkflowItem = @()
  if($null -ne $data.PCtrl.PrevAction) {
      $data.PCtrl.PrevAction | Where-Object {
          $item = $_
          $WorkflowItem += [PSCustomObject]@{
              Workflow = 'PrevAction'
              Priority = $item.Priority
              Label_ID = "$($($PowerControl.JsonCache.Pctrlitems.where({$_.id -eq $item.id}) | Select-Object Label).Label) - $($item.ID)"
              ID = $item.ID
          }
      }
  }

  if($null -ne $data.PCtrl.NextAction) {
      $data.PCtrl.NextAction | Where-Object {
          $item = $_
          $WorkflowItem += [PSCustomObject]@{
              Workflow = 'NextAction'
              Priority = $item.Priority
              Label_ID = "$($($PowerControl.JsonCache.Pctrlitems.where({$_.id -eq $item.id}) | Select-Object Label).Label) - $($item.ID)"
              ID = $item.ID
          }
      }
  }

  $WorkflowTabElements = @{
    'Label' = 'Data Grid:'
    'DataGrid' = @{
        'Name' = 'ManageWorkflow'
        'AddRows' = $true
        'Filter' = $true
        'Columns' = @(
            @{
                'Type' = 'ComboBoxColumn'
                'Header' = 'Workflow'
                'Binding' = 'Workflow'
                'Width' = 'Auto'
                'Items' = @('PrevAction','NextAction')
            },
            @{
                'Type' = 'TextColumn'
                'Header' = 'Priority'
                'Binding' = 'Priority'
                'Width' = '50'
            },
            @{
                'Type' = 'ComboBoxColumn'
                'Header' = 'Label_ID'
                'Binding' = 'Label_ID'
                'Width' = 'Auto'
                'Items' = $ListBoxItems
            },
            @{
                'Type' = 'TextColumn'
                'Header' = 'ID'
                'Binding' = 'ID'
                'Width' = 'Auto'
            }
        )
        'Rows' = $WorkflowItem
    }
}

  # Tabs
  $tabs = @(
      @{
          'Header' = '_Important'
          'Elements' = $importantTabElements
      },
      @{
          'Header' = '_Misc'
          'Elements' = $miscTabElements
      },
      @{
          'Header' = '_Key Binding'
          'Elements' = $keyBindingTabElements
      },
      @{
          'Header' = '_Workflow'
          'Elements' = $WorkflowTabElements
      }
  )


  if ($data.PCtrl.type -ne 'Action') {
      $ListBoxItems = @()

      $PowerControl.JsonCache.Pctrlitems.where({$_.type -eq $data.PCtrl.type}) | Sort-Object Label | Select-Object id, Label | ForEach-Object {
          $ListBoxItems += "$($_.Label) - $($_.id) "
      }

      $childrenTabElements = @(
          @{
              'GroupBox' = @{
                  'Header' = 'Children'
                  'Elements' = @(
                      @{
                          'Label' = 'Children'
                          'ListBox' = @{
                              'Name' = 'Children'
                              'Items' = $ListBoxItems
                              'Text' = $(if($data.PCtrl.Children.count -gt 0) {@($data.PCtrl.Children -split ',').Trim()}else{})
                          }
                      }
                  )
              }
          }
      )

      $tabs += @{
          'Header' = '_Children'
          'Elements' = $childrenTabElements
      }
  }

  # Action buttons; the second one saves and then asks the shell to run the dry run of this element (UI command RunPending)
  $script:PowerControlAfterSave = $null
  $actionButtons = @{
      0 = @{
          'Label' = '_Save'
          'Name' = 'Save'
          'isDefault' = $true
      }
      1 = @{
          'Label' = 'Save + _Dry run'
          'Name' = 'SaveAndTest'
          'Code' = { $script:PowerControlAfterSave = 'DryRun' }
      }
  }

  # Main GUI table
  $GUItable = @{
      'window' = $windowSettings
      'dialog' = @{
          0 = @{
              'TabControl' = @{
                  'Name' = 'ImportantSettings'
                  'Tabs' = $tabs
              }
          }
      }
      'actionButtons' = $actionButtons
      'OnResult' = {
          # Load the existing XML file


          $private:PowerControlItem = $PowerControl.JsonCache.Pctrlitems.where({$_.id -eq $data.PCtrl.ID}, 'First')[0]

          $xmlPath = $PowerControl.General.enginePath + '\' + $private:PowerControlItem.file

          $xmlDoc = New-Object System.Xml.XmlDocument
          $xmlDoc.Load($xmlPath)

          # Find the Engine element
          $PCtrlElement = $xmlDoc.SelectNodes('/Engine/PCtrl').Where({$_.id -eq $data.PCtrl.ID}, 'First')[0]
          if ($null -eq $PCtrlElement) {
              throw "PCtrl element '$($data.PCtrl.ID)' was not found in $xmlPath"
          }

          # Set attributes for PCtrl if they have content
          if ($GUIResults.Type.Content) {
              $PCtrlElement.SetAttribute("type", $GUIResults.Type.Content)
          } elseif ($PCtrlElement.HasAttribute("type")) {
              $PCtrlElement.RemoveAttribute("type")
          }

          if ($GUIResults.ElementName) {
              $PCtrlElement.SetAttribute("Label", $GUIResults.ElementName)
          } elseif ($PCtrlElement.HasAttribute("Label")) {
              $PCtrlElement.RemoveAttribute("Label")
          }

          if ($GUIResults.Children -and $GUIResults.Children.Count -gt 0) {
              $selectedIDs = @()
              foreach ($child in $GUIResults.Children) {
                  if ($child.Content -match '-\s*(\S+)$') {
                      $selectedIDs += $matches[1]
                  }
              }
              # the list box returns the selection in list order (alphabetical); the Children order is the order
              # of the entries in the navigation and menus, so the existing order is kept and new ones go last
              $existingIDs = @(([string]$pctrlElement.GetAttribute("Children")) -split ',' | ForEach-Object { $_.Trim() } | Where-Object { $_ })
              $childrenIDs = @($existingIDs | Where-Object { $selectedIDs -contains $_ }) + @($selectedIDs | Where-Object { $existingIDs -notcontains $_ })
              if ($childrenIDs.Count -gt 0) {
                  $pctrlElement.SetAttribute("Children", $childrenIDs -join ',')
              }
          } else {
              $pctrlElement.RemoveAttribute("Children")
          }

          $iconValue = if ($GUIResults.Icon -is [string]) { $GUIResults.Icon } elseif ($null -ne $GUIResults.Icon) { [string]$GUIResults.Icon.Content } else { '' }
          if ($iconValue) {
              $PCtrlElement.SetAttribute("Icon", $iconValue.Replace($PowerControl.General.CurrentPath + '\icons\', $null))
          } elseif ($PCtrlElement.HasAttribute("Icon")) {
              $PCtrlElement.RemoveAttribute("Icon")
          }

          # Handle Description element
          $descriptionElement = $PCtrlElement.SelectSingleNode("Description")
          if ($GUIResults.Description) {
              if (-not $descriptionElement) {
                  $descriptionElement = $xmlDoc.CreateElement("Description")
                  $PCtrlElement.AppendChild($descriptionElement) 2>&1 | Out-Null
              }
              $descriptionElement.InnerXml = "`n<!--`n" + $GUIResults.Description + "`n-->`n"
          } elseif ($descriptionElement) {
              $PCtrlElement.RemoveChild($descriptionElement)
          }

          if ($GUIResults.ToolTip) {
              $PCtrlElement.SetAttribute("ToolTip", $GUIResults.ToolTip)
          } elseif ($PCtrlElement.HasAttribute("ToolTip")) {
              $PCtrlElement.RemoveAttribute("ToolTip")
          }

          # Handle DisplayCondition element
          $displayConditionElement = $PCtrlElement.SelectSingleNode("DisplayCondition")
          if ($GUIResults.DisplayCondition -or $GUIResults.Category -or $GUIResults.SortOrder) {
              if (-not $displayConditionElement) {
                  $displayConditionElement = $xmlDoc.CreateElement("DisplayCondition")
                  $PCtrlElement.AppendChild($displayConditionElement) 2>&1 | Out-Null
              }

              if ($GUIResults.Category) {
                  $displayConditionElement.SetAttribute("Categorie", $GUIResults.Category)
              } elseif ($displayConditionElement.HasAttribute("Categorie")) {
                  $displayConditionElement.RemoveAttribute("Categorie")
              }

              if ($GUIResults.SortOrder) {
                  $displayConditionElement.SetAttribute("SortOrder", $GUIResults.SortOrder)
              } elseif ($displayConditionElement.HasAttribute("SortOrder")) {
                  $displayConditionElement.RemoveAttribute("SortOrder")
              }

              if ($GUIResults.DisplayCondition) {
                  $cdataSection = $xmlDoc.CreateCDataSection($GUIResults.DisplayCondition)
                  $displayConditionElement.InnerXml = ""
                  $displayConditionElement.AppendChild($cdataSection) 2>&1 | Out-Null
              }
          } elseif ($displayConditionElement) {
              $PCtrlElement.RemoveChild($displayConditionElement)
          }

          # Handle KeyBinding element
          $keyBindingElement = $PCtrlElement.SelectSingleNode("KeyBinding")
          if ($GUIResults.key -or $GUIResults.Modifiers.Content) {
              if (-not $keyBindingElement) {
                  $keyBindingElement = $xmlDoc.CreateElement("KeyBinding")
                  $PCtrlElement.AppendChild($keyBindingElement) 2>&1 | Out-Null
              }

              if ($GUIResults.key) {
                  $keyBindingElement.SetAttribute("Key", $GUIResults.key)
              } elseif ($keyBindingElement.HasAttribute("Key")) {
                  $keyBindingElement.RemoveAttribute("Key")
              }

              if ($GUIResults.Modifiers.Content) {
                  $keyBindingElement.SetAttribute("Modifiers", $GUIResults.Modifiers.Content)
              } elseif ($keyBindingElement.HasAttribute("Modifiers")) {
                  $keyBindingElement.RemoveAttribute("Modifiers")
              }
          } elseif ($keyBindingElement) {
              $PCtrlElement.RemoveChild($keyBindingElement)
          }

          # Handle Script element
          $scriptElement = $PCtrlElement.SelectSingleNode("Script")
          if ($GUIResults.Script) {
              if (-not $scriptElement) {
                  $scriptElement = $xmlDoc.CreateElement("Script")
                  $PCtrlElement.AppendChild($scriptElement) 2>&1 | Out-Null
              }
              $cdataSection = $xmlDoc.CreateCDataSection($GUIResults.Script)
              $scriptElement.InnerXml = ""
              $scriptElement.AppendChild($cdataSection) 2>&1 | Out-Null
          } elseif ($scriptElement) {
              $PCtrlElement.RemoveChild($scriptElement)
          }

          if ($GUIResults['ManageWorkflow']) {
              # Remove existing workflow actions if they exist
              # remove ALL existing workflow nodes. SelectSingleNode only removed the first one,
              # so every save duplicated the remaining PrevAction/NextAction entries.
              foreach ($oldWorkflowNode in @($PCtrlElement.SelectNodes("PrevAction|NextAction"))) {
                  $PCtrlElement.RemoveChild($oldWorkflowNode) 2>&1 | Out-Null
              }


              foreach ($action in $GUIResults['ManageWorkflow']) {
                  if ($action.Workflow -eq "PrevAction") {
                      $prevActionElement = $xmlDoc.CreateElement("PrevAction")
                      $prevActionElement.SetAttribute("ID", $(if ($action.Label_ID -match '-\s*(\S+)\s*$') { $matches[1] } else { $action.ID }))
                      $prevActionElement.SetAttribute("Priority", $action.Priority)
                      $PCtrlElement.AppendChild($prevActionElement) 2>&1 | Out-Null
                  }
                  elseif ($action.Workflow -eq "NextAction") {
                      $nextActionElement = $xmlDoc.CreateElement("NextAction")
                      $nextActionElement.SetAttribute("ID", $(if ($action.Label_ID -match '-\s*(\S+)\s*$') { $matches[1] } else { $action.ID }))
                      $nextActionElement.SetAttribute("Priority", $action.Priority)
                      $PCtrlElement.AppendChild($nextActionElement) 2>&1 | Out-Null
                  }
              }
          }

          # Save the modified XML back to the file
          Save-PowerControlXml -XmlDocument $xmlDoc -Path $xmlPath -RefreshIndex
      }
  }

  Show-PCtrlGUI -GUItable $GUItable

  if ($script:PowerControlAfterSave -eq 'DryRun') {
      # "Speichern + Dry Run": the element was saved (OnResult), now the shell runs the dry run action for it as a new job
      $script:PowerControlAfterSave = $null
      $PowerControl.UI.PendingRun = @{ ID = 'DryRun-0a1b2c3d4e5f60718293a4b5c6d7e8f9'; Entries = @([PSCustomObject]@{ id = [string]$elementID; Label = [string]$data.PCtrl.Label; type = [string]$data.PCtrl.type }) }
      Invoke-PowerControlUICommand -Name RunPending
  }

  $Global:PowerControl.EventParams.sender = $null
  $Global:PowerControl.EventParams.args = $null
}


# rows and columns are read on the UI thread by the core helper; touching $OutputGrid.Items
# from this runspace thread is a cross-thread access to a WPF object
$gridData = Get-PowerControlGridData

$windowSettings = @{
    'title' = 'Edit rows'
}

$actionButtons = @{
  0 = @{
      'Label' = '_Save'
      'Name' = 'Save'
      'isDefault' = $true
  }
}

$Columns = @(
  foreach ($prop in ($gridData.Rows | Select-Object -First 1).PSObject.Properties.Name) {
      @{
          'Type' = 'TextColumn'
          'Header' = $prop
          'Binding' = $prop
          'Width' = 'Auto'
      }
  }
)

$GUItable = @{
      'window' = $windowSettings
      'dialog' = @{
          0 = @{
              'DataGrid' = @{
                  'Name' = 'EditDataGrid'
                  'Columns' = $Columns
                  'Rows' = $gridData.Rows
              }
          }
      }
      'actionButtons' = $actionButtons
      'OnResult' = {
      		foreach ($item in $GUIResults['EditDataGrid']) {
				$Script:PowerControlItem_Output += $item
			}
      }
  } 


Show-PCtrlGUI -GUItable $GUItable

$selected = @($script:SelectedEntries | Where-Object { $_.id })
if ($selected.Count -eq 0) { throw 'No elements selected.' }
foreach ($row in $selected) {
  $Script:PowerControlItem_Output += [PSCustomObject]@{ Dialog = '(element)'; Field = [string]$row.Label; Value = [string]$row.id; Type = [string]$row.type }
  # Show-PCtrlGUI (Draw GUI) checks this flag: dialog values become rows, OnResult is not executed
  $script:PowerControlDryRun = $true
  $before = @($Script:PowerControlItem_Output).Count
  try { $null = Get-ActionSequence -ID $row.id | Invoke-ActionScript 6>&1 }
  finally { $script:PowerControlDryRun = $false }
  if (@($Script:PowerControlItem_Output).Count -eq $before) {
    # nothing reported: no Draw GUI dialog in the sequence, or the dialog was cancelled
    $Script:PowerControlItem_Output += [PSCustomObject]@{ Dialog = '(note)'; Field = ''; Value = 'no Draw GUI dialog was confirmed: the element has no Show-PCtrlGUI dialog or the dialog was cancelled'; Type = '' }
  }
}

$selected = @($script:SelectedEntries | Where-Object { $_.id })
if ($selected.Count -eq 0) { throw 'No elements selected.' }
$docs = @{}
foreach ($row in $selected) {
  $entry = $PowerControl.JsonCache.PCtrlItems | Where-Object { $_.id -eq $row.id } | Select-Object -First 1
  if ($null -eq $entry) { continue }
  $path = Join-Path $PowerControl.General.enginePath $entry.file
  if (-not $docs.ContainsKey($path)) { $d = [System.Xml.XmlDocument]::new(); $d.PreserveWhitespace = $true; $d.Load($path); $docs[$path] = $d }
  $doc = $docs[$path]
  $node = $doc.SelectSingleNode("//PCtrl[@ID='$(([string]$row.id).Replace("'", '&apos;'))']")
  if ($null -eq $node) { continue }
  $copy = $node.CloneNode($true)
  $label = $node.GetAttribute('Label')
  $newId = (($label -replace '[^A-Za-z0-9]', '') + '-' + [guid]::NewGuid().ToString('N').Substring(0, 24))
  $copy.SetAttribute('ID', $newId)
  $copy.SetAttribute('Label', "$label (copy)")
  # a copy must not steal the key binding
  $binding = $copy.SelectSingleNode('KeyBinding'); if ($null -ne $binding) { [void]$copy.RemoveChild($binding) }
  [void]$node.ParentNode.InsertAfter($doc.CreateWhitespace("`n  "), $node)
  [void]$node.ParentNode.InsertAfter($copy, $node.NextSibling)
  # the copy joins every group the original belongs to (Children list of the parent), right after the
  # original; otherwise it would show up as a separate top-level entry
  $parents = @()
  foreach ($parent in $PowerControl.JsonCache.PCtrlItems) {
    if (-not $parent.Children) { continue }
    $childIds = @(([string]$parent.Children).Split(',') | ForEach-Object { $_.Trim() })
    if ($childIds -notcontains [string]$row.id) { continue }
    $parentPath = Join-Path $PowerControl.General.enginePath $parent.file
    if (-not $docs.ContainsKey($parentPath)) { $d = [System.Xml.XmlDocument]::new(); $d.PreserveWhitespace = $true; $d.Load($parentPath); $docs[$parentPath] = $d }
    $parentNode = $docs[$parentPath].SelectSingleNode("//PCtrl[@ID='$(([string]$parent.id).Replace("'", '&apos;'))']")
    if ($null -eq $parentNode) { continue }
    $index = [Array]::IndexOf($childIds, [string]$row.id)
    $newChildren = @($childIds[0..$index]) + @($newId) + @(if ($index + 1 -lt $childIds.Count) { $childIds[($index + 1)..($childIds.Count - 1)] })
    $parentNode.SetAttribute('Children', ($newChildren -join ','))
    $parents += [string]$parent.Label
  }
  $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = "$label (copy)"; ID = $newId; File = $entry.file; Result = "created (key binding removed$(if ($parents.Count) { '; in group: ' + ($parents -join ', ') }))" }
}
$paths = @($docs.Keys)
for ($i = 0; $i -lt $paths.Count; $i++) { Save-PowerControlXml -XmlDocument $docs[$paths[$i]] -Path $paths[$i] -RefreshIndex:($i -eq $paths.Count - 1) }

$selected = @($script:SelectedEntries | Where-Object { $_.id })
if ($selected.Count -eq 0) { throw 'No elements selected.' }
$engineFiles = @(Get-ChildItem -Path (Join-Path $PowerControl.General.enginePath '*.xml') | ForEach-Object { $_.Name })
$asText = { param($value) if ($value -is [string]) { $value } elseif ($null -ne $value -and $null -ne $value.Content) { [string]$value.Content } else { [string]$value } }
$GUItable = @{
  'window' = @{ 'title' = 'Move element'; 'description' = "Moves $($selected.Count) element(s) into another engine file. A new name creates the file." }
  'dialog' = @{ 0 = @{ 'Label' = 'Target file'; 'ComboBox' = @{ 'Name' = 'Target'; 'IsEditable' = $true; 'Text' = $engineFiles[0]; 'Elements' = $engineFiles } } }
  'actionButtons' = @{ 0 = @{ 'Label' = '_Move'; 'Name' = 'Move'; 'isDefault' = $true } }
  'OnResult' = {
    $targetName = (& $asText $GUIResults.Target).Trim()
    if (-not $targetName) { throw 'No target file given.' }
    if (-not $targetName.EndsWith('.xml')) { $targetName += '.xml' }
    $targetPath = Join-Path $PowerControl.General.enginePath $targetName
    $target = [System.Xml.XmlDocument]::new(); $target.PreserveWhitespace = $true
    if (Test-Path -LiteralPath $targetPath) { $target.Load($targetPath) } else { [void]$target.AppendChild($target.CreateXmlDeclaration('1.0', 'utf-8', $null)); [void]$target.AppendChild($target.CreateElement('Engine')) }
    $docs = @{ $targetPath = $target }
    foreach ($row in $selected) {
      $entry = $PowerControl.JsonCache.PCtrlItems | Where-Object { $_.id -eq $row.id } | Select-Object -First 1
      if ($null -eq $entry) { continue }
      $sourcePath = Join-Path $PowerControl.General.enginePath $entry.file
      if ($sourcePath -eq $targetPath) { $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = $entry.Label; ID = $row.id; Result = 'already in the target file'; File = $targetName }; continue }
      if (-not $docs.ContainsKey($sourcePath)) { $d = [System.Xml.XmlDocument]::new(); $d.PreserveWhitespace = $true; $d.Load($sourcePath); $docs[$sourcePath] = $d }
      $node = $docs[$sourcePath].SelectSingleNode("//PCtrl[@ID='$(([string]$row.id).Replace("'", '&apos;'))']")
      if ($null -eq $node) { continue }
      [void]$node.ParentNode.RemoveChild($node)
      [void]$target.DocumentElement.AppendChild($target.CreateWhitespace("`n  "))
      [void]$target.DocumentElement.AppendChild($target.ImportNode($node, $true))
      $Script:PowerControlItem_Output += [PSCustomObject]@{ Label = $entry.Label; ID = $row.id; Result = "moved from $($entry.file)"; File = $targetName }
    }
    [void]$target.DocumentElement.AppendChild($target.CreateWhitespace("`n"))
    $paths = @($docs.Keys | Where-Object { $_ -ne $targetPath })
    foreach ($path in $paths) { Save-PowerControlXml -XmlDocument $docs[$path] -Path $path }
    Save-PowerControlXml -XmlDocument $target -Path $targetPath -RefreshIndex
  }
}
Show-PCtrlGUI -GUItable $GUItable



$script:PowerControl.SynchronizedWindow.Dispatcher.Invoke({
    $script:OutputGrid = [System.Windows.LogicalTreeHelper]::FindLogicalNode(
        $script:PowerControl.SynchronizedWindow,
        'OutputGrid'
    )
    $script:OutputGrid.Columns.where({$_.header -eq $script:PowerControl.EventParams.sender.PlacementTarget})[0].Visibility = [System.Windows.Visibility]::Collapsed
})

$Global:PowerControl.EventParams.sender = $null
$Global:PowerControl.EventParams.args = $null


$script:PowerControl.SynchronizedWindow.Dispatcher.Invoke({
    $script:OutputGrid = [System.Windows.LogicalTreeHelper]::FindLogicalNode(
        $script:PowerControl.SynchronizedWindow,
        'OutputGrid'
    )

    for ($i = 0; $i -lt $script:OutputGrid.Columns.Count; $i++) {
      $col = $script:OutputGrid.Columns[$i]
      $col.Visibility = [System.Windows.Visibility]::Visible
    }

})
